/* Generated by scripts/build-daily-pool.ts from the PNA Teacher lessons. Do not edit by hand. */
export type GeneratedDailyQuestion = { id: string; topic: string; question: string; options: string[]; correct: number; explanation: string; href: string; linkTitle: string };
export const generatedDailyPool: GeneratedDailyQuestion[] = [{"id":"lq-abpi-and-glucose-exercise-safety-1","topic":"Skills · Vitals & Monitoring","question":"The ankle systolic pressure is 90 mmHg and the higher arm pressure is 150 mmHg. What is the ABPI and its meaning?","options":["0.9 — normal","1.67 — normal","0.6 — moderate peripheral arterial disease"],"correct":2,"explanation":"Yes — 90 ÷ 150 = 0.6. Below 0.9 suggests arterial disease; roughly 0.5–0.9 is mild to moderate and below about 0.4 is severe.","href":"/learn/abpi-and-glucose-exercise-safety","linkTitle":"ABPI and Blood Glucose — Two Checks That Make Exercise Safer"},{"id":"lq-abpi-and-glucose-exercise-safety-2","topic":"Skills · Vitals & Monitoring","question":"A long-standing diabetic man has an ABPI of 1.4 and cramping calf pain on walking. How do you interpret this?","options":["It is normal, so there is no arterial problem","The vessels may be stiff and calcified, so the ABPI is unreliable; request a toe-brachial index or vascular assessment","It shows severe arterial disease"],"correct":1,"explanation":"Yes — an ABPI above 1.3 suggests non-compressible vessels, and claudication symptoms still need investigation.","href":"/learn/abpi-and-glucose-exercise-safety","linkTitle":"ABPI and Blood Glucose — Two Checks That Make Exercise Safer"},{"id":"lq-active-passive-insufficiency-1","topic":"Movement Science","question":"Back to the first experiment: wrist fully flexed, trying to make a fist. Which muscle group is PASSIVELY insufficient there?","options":["The finger flexors (front of the forearm)","The biceps","The finger extensors (back of the forearm)"],"correct":2,"explanation":"Yes! They're stretched over the flexed wrist AND the bending fingers, so they act as a brake. Active insufficiency of the flexors + passive insufficiency of the extensors = weak fist.","href":"/learn/active-passive-insufficiency","linkTitle":"Active & Passive Insufficiency — Feel It in Your Own Hand"},{"id":"lq-active-passive-insufficiency-2","topic":"Movement Science","question":"During a passive straight-leg raise, the leg stops at about 60° with tension behind the thigh. Which concept best explains this?","options":["Passive insufficiency of the hamstrings","Active insufficiency of the hip flexors","Active insufficiency of the hamstrings"],"correct":0,"explanation":"Correct — hip flexion with the knee straight stretches the hamstrings over both joints until they run out of length.","href":"/learn/active-passive-insufficiency","linkTitle":"Active & Passive Insufficiency — Feel It in Your Own Hand"},{"id":"lq-active-passive-insufficiency-3","topic":"Movement Science","question":"A patient lies prone with the hip extended and tries to bend the knee fully. Which muscle is most likely to become ACTIVELY insufficient?","options":["Rectus femoris","Gluteus maximus","Hamstrings"],"correct":2,"explanation":"Yes! Hip extension + knee flexion shortens the hamstrings at both joints — they lose force (and may even cramp) near full knee flexion.","href":"/learn/active-passive-insufficiency","linkTitle":"Active & Passive Insufficiency — Feel It in Your Own Hand"},{"id":"lq-active-release-style-soft-tissue-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Shortened position mean?","options":["The patient slowly moves the muscle to its long position themselves.","A gentle press on the target tissue.","The muscle's two ends brought close together."],"correct":2,"explanation":"Exactly! Shortened position — The muscle's two ends brought close together.","href":"/manual-therapy/active-release-style-soft-tissue","linkTitle":"Active Soft-Tissue Release"},{"id":"lq-active-release-style-soft-tissue-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Active Soft-Tissue Release (or to stop and reassess)?","options":["Overuse tightness, such as hamstring or forearm muscle restriction.","Acute tear, infection, open wounds or bleeding disorders.","When you want to combine hands-on work with movement."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/active-release-style-soft-tissue","linkTitle":"Active Soft-Tissue Release"},{"id":"lq-airway-clearance-acbt-1","topic":"Cardiorespiratory","question":"During ACBT, why is breathing control placed between the active parts?","options":["Because it clears most of the sputum","It's optional and can be skipped","To rest and prevent fatigue, breathlessness and bronchospasm"],"correct":2,"explanation":"Yes — the pauses keep the cycle comfortable and effective, especially in breathless patients.","href":"/learn/airway-clearance-acbt","linkTitle":"Airway Clearance — The Active Cycle of Breathing Technique (ACBT)"},{"id":"lq-airway-clearance-acbt-2","topic":"Cardiorespiratory","question":"Which patient should you NOT put in a head-down drainage position?","options":["A patient who prefers sitting","A patient with severe reflux and heart failure who gets breathless lying flat","A young adult with stable bronchiectasis and no other problems"],"correct":1,"explanation":"Yes — head-down tilt would worsen reflux and breathlessness. Use upright or side-lying ACBT.","href":"/learn/airway-clearance-acbt","linkTitle":"Airway Clearance — The Active Cycle of Breathing Technique (ACBT)"},{"id":"lq-airway-clearance-acbt-3","topic":"Cardiorespiratory","question":"Midway through ACBT, your bronchiectasis patient coughs up about a tablespoon of bright red blood. What do you do?","options":["Continue — blood-streaked sputum is common in bronchiectasis","Stop airway clearance, keep them upright and calm, check SpO₂ and get urgent medical review","Add percussion to clear the blood"],"correct":1,"explanation":"Yes — stop, monitor and escalate. Clearance resumes only when the medical team agrees.","href":"/learn/airway-clearance-acbt","linkTitle":"Airway Clearance — The Active Cycle of Breathing Technique (ACBT)"},{"id":"lq-ankle-sprain-ottawa-syndesmosis-1","topic":"Skills · Measurement","question":"After an inversion injury a patient has tenderness at the back edge of the lateral malleolus. What do the Ottawa rules say?","options":["Do a talar tilt only","Arrange an ankle X-ray","Start loading immediately without imaging"],"correct":1,"explanation":"Yes — bone tenderness at the back edge or tip of a malleolus needs an X-ray.","href":"/learn/ankle-sprain-ottawa-syndesmosis","linkTitle":"The Twisted Ankle — Ottawa Rules, Ligament Tests and the High Ankle Sprain"},{"id":"lq-ankle-sprain-ottawa-syndesmosis-2","topic":"Skills · Measurement","question":"Where must the pain be felt for the squeeze test to be positive?","options":["At the place where the calf is squeezed","In the heel","At the ankle, between the tibia and fibula, away from the squeeze"],"correct":2,"explanation":"Yes — that is the sign of syndesmosis injury.","href":"/learn/ankle-sprain-ottawa-syndesmosis","linkTitle":"The Twisted Ankle — Ottawa Rules, Ligament Tests and the High Ankle Sprain"},{"id":"lq-ankle-sprain-ottawa-syndesmosis-3","topic":"Skills · Measurement","question":"When are the ankle drawer and talar tilt tests most accurate?","options":["Immediately after the injury","Four to five days after the injury, when swelling and guarding have settled","Only after surgery"],"correct":1,"explanation":"Yes — a delayed examination is more accurate than one in the first hours.","href":"/learn/ankle-sprain-ottawa-syndesmosis","linkTitle":"The Twisted Ankle — Ottawa Rules, Ligament Tests and the High Ankle Sprain"},{"id":"lq-arm-nerve-injuries-1","topic":"Skills · Neuro Exam","question":"A man wakes after sleeping with his arm over the back of a chair. He cannot extend his wrist or fingers and there is a numb patch over the back of the first web space. Which nerve?","options":["Ulnar nerve at the elbow","Median nerve at the carpal tunnel","Radial nerve at the spiral groove (wrist drop)"],"correct":2,"explanation":"Yes — \"Saturday-night palsy\": compression of the radial nerve against the humerus. Triceps is spared because the nerve to it leaves higher up.","href":"/learn/arm-nerve-injuries","linkTitle":"Arm Nerve Injuries — Radial, Median, Ulnar, Axillary and More"},{"id":"lq-arm-nerve-injuries-2","topic":"Skills · Neuro Exam","question":"After a mastectomy a woman notices the inner border of her scapula sticking out when she pushes her hand against a wall. Which nerve?","options":["Long thoracic nerve (serratus anterior)","Spinal accessory nerve","Axillary nerve"],"correct":0,"explanation":"Yes — it runs along the chest wall and is easily injured in axillary surgery.","href":"/learn/arm-nerve-injuries","linkTitle":"Arm Nerve Injuries — Radial, Median, Ulnar, Axillary and More"},{"id":"lq-arm-nerve-injuries-3","topic":"Skills · Neuro Exam","question":"Which statement about the autonomous zone is correct?","options":["It is the whole area a nerve touches, including overlap","It only matters for motor nerves","It is the patch of skin supplied by only one nerve, so testing there gives the clearest answer"],"correct":2,"explanation":"Yes — neighbouring nerves overlap elsewhere, so a loss in the autonomous zone is the reliable one.","href":"/learn/arm-nerve-injuries","linkTitle":"Arm Nerve Injuries — Radial, Median, Ulnar, Axillary and More"},{"id":"lq-balance-falls-assessment-1","topic":"Neurology","question":"A diabetic man stands steadily with eyes open but sways and steps within 5 seconds of closing his eyes. Which system is most likely impaired?","options":["Cerebellum","Vision","Somatosensory — peripheral neuropathy"],"correct":2,"explanation":"Yes — a positive Romberg with diabetes points to loss of foot proprioception. Check sensation and footwear, and warn about the dark.","href":"/learn/balance-falls-assessment","linkTitle":"Balance Systems & Falls Assessment — From Romberg to TUG"},{"id":"lq-balance-falls-assessment-2","topic":"Neurology","question":"A 74-year-old completes the TUG in 18 seconds and needs her hands to stand up. What is the best interpretation?","options":["She must stop walking outside","Normal for her age","Increased falls risk — do a fuller falls assessment and start strength and balance training"],"correct":2,"explanation":"Yes — combine with history (previous falls, medicines, vision, home) for a full picture.","href":"/learn/balance-falls-assessment","linkTitle":"Balance Systems & Falls Assessment — From Romberg to TUG"},{"id":"lq-balance-falls-assessment-3","topic":"Neurology","question":"Which programme best follows the falls-prevention evidence for a fit-enough 70-year-old?","options":["A daily 20-minute walk only","Seated stretches twice a week","Progressive balance and leg-strength exercises, about 3+ hours a week in total, continued long-term"],"correct":2,"explanation":"Yes — high balance challenge, adequate dose and continuation are what work.","href":"/learn/balance-falls-assessment","linkTitle":"Balance Systems & Falls Assessment — From Romberg to TUG"},{"id":"lq-balanced-ligamentous-tension-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Point of balance mean?","options":["The pull felt from ligaments holding bones together.","A sense of softening or settling, interpreted by the practitioner.","The position where tissue tension feels equal around the joint."],"correct":2,"explanation":"Exactly! Point of balance — The position where tissue tension feels equal around the joint.","href":"/manual-therapy/balanced-ligamentous-tension","linkTitle":"Balanced Ligamentous Tension (BLT)"},{"id":"lq-balanced-ligamentous-tension-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Balanced Ligamentous Tension (BLT) (or to stop and reassess)?","options":["Fractures, instability, infection or unexplained severe pain.","Gentle treatment of joints or soft tissues in people who cannot tolerate firm techniques.","Practitioners trained in osteopathic methods."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/balanced-ligamentous-tension","linkTitle":"Balanced Ligamentous Tension (BLT)"},{"id":"lq-balanced-ligamentous-tension-4","topic":"Manual Therapy · World Approaches","question":"Which explanation is scientifically responsible after a comfortable BLT session?","options":["A change in comfort may occur; reassess function without claiming structural correction.","A painless session guarantees long-term cure.","A ligament certainly snapped into its correct anatomical place."],"correct":0,"explanation":"Comfort or symptom change is observable; exact ligament 'reset' mechanisms are not established.","href":"/manual-therapy/balanced-ligamentous-tension","linkTitle":"Balanced Ligamentous Tension (BLT)"},{"id":"lq-bowen-technique-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Bowenwork mean?","options":["The practice named after Tom Bowen.","A rest period built into the sequence.","A gentle roll over a muscle or tendon."],"correct":0,"explanation":"Exactly! Bowenwork — The practice named after Tom Bowen.","href":"/manual-therapy/bowen-technique","linkTitle":"Bowen Technique / Bowenwork"},{"id":"lq-bowen-technique-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Bowen Technique / Bowenwork (or to stop and reassess)?","options":["Red flags, progressive weakness, severe headache or serious illness.","Alongside, not instead of, exercise and medical care.","Someone who wants a gentle, relaxing option after screening."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/bowen-technique","linkTitle":"Bowen Technique / Bowenwork"},{"id":"lq-bowen-technique-4","topic":"Manual Therapy · World Approaches","question":"Someone claims Bowen pauses permanently reset the nervous system. Which response is best?","options":["That mechanism is not established; judge evidence and meaningful outcomes.","That claim eliminates the need for medical evaluation.","It must be true because the session was relaxing."],"correct":0,"explanation":"The claimed neurological reset is not an established physiological finding and relaxation alone is not efficacy evidence.","href":"/manual-therapy/bowen-technique","linkTitle":"Bowen Technique / Bowenwork"},{"id":"lq-bppv-dix-hallpike-epley-1","topic":"Neurology","question":"Which story best fits BPPV?","options":["Constant spinning for two days with nausea, worse with any movement","Sudden vertigo with double vision and trouble speaking","Spinning for about 20 seconds when rolling over in bed or looking up, normal when still"],"correct":2,"explanation":"Yes — brief, position-triggered spinning with nothing between episodes is classic BPPV.","href":"/learn/bppv-dix-hallpike-epley","linkTitle":"BPPV: Dix-Hallpike, the Epley Manoeuvre and When Not to Treat"},{"id":"lq-bppv-dix-hallpike-epley-2","topic":"Neurology","question":"During a Dix-Hallpike test the eyes beat DOWNWARD, start instantly, do not fade and the patient also has a new unsteady gait. What do you conclude?","options":["A normal test; the patient is anxious","A central cause is likely: do not treat, refer urgently","A posterior-canal BPPV, so go ahead with the Epley manoeuvre"],"correct":1,"explanation":"Yes — downbeating nystagmus without latency or fatigue, with an unsteady gait, breaks the BPPV rules and points to the brainstem or cerebellum.","href":"/learn/bppv-dix-hallpike-epley","linkTitle":"BPPV: Dix-Hallpike, the Epley Manoeuvre and When Not to Treat"},{"id":"lq-bppv-dix-hallpike-epley-3","topic":"Neurology","question":"What is the aim of the Epley manoeuvre?","options":["To move the loose crystals out of the posterior canal back into the utricle, using gravity and head positions","To stretch the neck muscles that cause the dizziness","To make the patient so dizzy that the brain gets used to it"],"correct":0,"explanation":"Yes — the sequence of positions rolls the crystals round the canal and out through its opening.","href":"/learn/bppv-dix-hallpike-epley","linkTitle":"BPPV: Dix-Hallpike, the Epley Manoeuvre and When Not to Treat"},{"id":"lq-cardiac-rehabilitation-phases-1","topic":"Cardiorespiratory","question":"What effort level on the Borg 6 to 20 scale is usual for cardiac rehabilitation?","options":["About 11 to 14, fairly light to somewhat hard","19 to 20, maximal effort","6 to 8, almost no effort"],"correct":0,"explanation":"Yes — moderate effort with the ability to talk.","href":"/learn/cardiac-rehabilitation-phases","linkTitle":"Cardiac Rehabilitation — Exercising Safely After a Heart Event"},{"id":"lq-cardiac-rehabilitation-phases-2","topic":"Cardiorespiratory","question":"Which finding means stop the exercise session?","options":["Chest pain, severe breathlessness, dizziness or a fall in blood pressure","Mild sweating","A heart rate rise within the planned range"],"correct":0,"explanation":"Yes — sit the person down, check vital signs and seek help if it persists.","href":"/learn/cardiac-rehabilitation-phases","linkTitle":"Cardiac Rehabilitation — Exercising Safely After a Heart Event"},{"id":"lq-cardiac-rehabilitation-phases-3","topic":"Cardiorespiratory","question":"After bypass surgery through the breastbone, which advice is usual?","options":["Do press-ups from week one","Avoid heavy lifting and pushing with the arms for the first weeks, as the surgeon advises","Avoid walking completely"],"correct":1,"explanation":"Yes — protect the healing breastbone.","href":"/learn/cardiac-rehabilitation-phases","linkTitle":"Cardiac Rehabilitation — Exercising Safely After a Heart Event"},{"id":"lq-carpal-tunnel-hand-nerve-examination-1","topic":"Skills · Neuro Exam","question":"Numbness in the thumb, index and middle fingers that wakes the patient at night and eases with shaking the hand. What is most likely?","options":["Cubital tunnel syndrome","A rotator cuff tear","Carpal tunnel syndrome"],"correct":2,"explanation":"Yes — median nerve fingers, night symptoms and relief on shaking are the typical picture.","href":"/learn/carpal-tunnel-hand-nerve-examination","linkTitle":"Numb Hands — Carpal Tunnel, Cubital Tunnel and the Neck"},{"id":"lq-carpal-tunnel-hand-nerve-examination-2","topic":"Skills · Neuro Exam","question":"Which finding means the compression has been going on for a long time?","options":["Tingling at night only","Wasting of the thenar muscle with weak thumb abduction","A positive Tinel's sign alone"],"correct":1,"explanation":"Yes — muscle wasting is a late sign and needs a specialist opinion.","href":"/learn/carpal-tunnel-hand-nerve-examination","linkTitle":"Numb Hands — Carpal Tunnel, Cubital Tunnel and the Neck"},{"id":"lq-carpal-tunnel-hand-nerve-examination-3","topic":"Skills · Neuro Exam","question":"Numbness only in the little finger and half of the ring finger, worse after leaning on the elbow. Where is the problem most likely?","options":["At the wrist, the median nerve","In the shoulder joint","At the elbow, the ulnar nerve in the cubital tunnel"],"correct":2,"explanation":"Yes — these fingers and the elbow trigger point to the ulnar nerve.","href":"/learn/carpal-tunnel-hand-nerve-examination","linkTitle":"Numb Hands — Carpal Tunnel, Cubital Tunnel and the Neck"},{"id":"lq-cerebellar-exam-coordination-1","topic":"Skills · Neuro Exam","question":"A patient's finger shakes more and more as it approaches the examiner's finger and then overshoots. What is this?","options":["A normal finding","Intention tremor and dysmetria (a cerebellar sign)","A resting (Parkinsonian) tremor"],"correct":1,"explanation":"Yes — the tremor appears with purposeful movement and worsens near the target. A resting tremor is different (Parkinson's disease).","href":"/learn/cerebellar-exam-coordination","linkTitle":"The Cerebellar Exam — Finger-Nose, Rapid Movements, Heel-Shin and DANISH"},{"id":"lq-cerebellar-exam-coordination-2","topic":"Skills · Neuro Exam","question":"A patient is unsteady with eyes open and equally unsteady with eyes closed, with nystagmus and slurred speech. Which type of ataxia?","options":["Sensory ataxia","Functional (non-organic) gait","Cerebellar ataxia"],"correct":2,"explanation":"Yes — no extra loss with eyes closed, plus nystagmus and dysarthria, means the cerebellum.","href":"/learn/cerebellar-exam-coordination","linkTitle":"The Cerebellar Exam — Finger-Nose, Rapid Movements, Heel-Shin and DANISH"},{"id":"lq-cerebellar-exam-coordination-3","topic":"Skills · Neuro Exam","question":"Which test is the most sensitive bedside test for mild cerebellar disease?","options":["Tandem (heel-to-toe) walking","Knee jerk","Finger-to-nose with eyes open"],"correct":0,"explanation":"Yes — a failure to walk a straight line is often the first sign.","href":"/learn/cerebellar-exam-coordination","linkTitle":"The Cerebellar Exam — Finger-Nose, Rapid Movements, Heel-Shin and DANISH"},{"id":"lq-cerebral-palsy-gmfcs-1","topic":"Paediatrics","question":"A 9-year-old walks at school with a walker, climbs stairs holding a rail with help, and uses a manual wheelchair for outings. Which GMFCS level?","options":["Level III: walks using a handheld mobility device, wheeled mobility for distance","Level V: transported in a wheelchair in all settings","Level I: walks without limitations"],"correct":0,"explanation":"Yes — Level III children walk with a handheld device indoors and use wheeled mobility for longer distances or outdoors.","href":"/learn/cerebral-palsy-gmfcs","linkTitle":"Cerebral Palsy and the GMFCS: Levels I to V, Hips and Goals"},{"id":"lq-cerebral-palsy-gmfcs-2","topic":"Paediatrics","question":"A 5-year-old walks well indoors and outdoors, climbs stairs without help, and is just starting to run and jump, though more slowly and clumsily than other children. Which level?","options":["Level II","Level I","Level III"],"correct":1,"explanation":"Yes — he walks without a device and without limits; reduced speed, balance and coordination are the Level I limitation.","href":"/learn/cerebral-palsy-gmfcs","linkTitle":"Cerebral Palsy and the GMFCS: Levels I to V, Hips and Goals"},{"id":"lq-cerebral-palsy-gmfcs-3","topic":"Paediatrics","question":"A 6-year-old child with CP at GMFCS Level IV, who uses a power chair, has two weeks of new pain on the left side of the groin that hurts when his hips are moved, and he has lost his ability to stand in his stander. What should you do?","options":["Continue as planned; pain is part of cerebral palsy","Increase the stretching to restore the range","Stop the stretching and standing, treat it as a possible hip displacement or fracture and arrange an urgent medical and X-ray review"],"correct":2,"explanation":"Yes — new pain with loss of function in a high-risk child (and fragile bones) needs imaging before any further loading.","href":"/learn/cerebral-palsy-gmfcs","linkTitle":"Cerebral Palsy and the GMFCS: Levels I to V, Hips and Goals"},{"id":"lq-cervical-manipulation-safety-screening-1","topic":"Manual Therapy","question":"A patient has sudden \"worst ever\" neck pain after a fall, with a headache and a droopy eyelid. What do you do?","options":["Reassure and book a follow-up in a week","Do not treat the neck and arrange emergency medical care","Do a gentle manipulation to relieve the pain"],"correct":1,"explanation":"Yes — pain like this with a droopy eyelid (Horner's) suggests an artery dissection, which is an emergency.","href":"/learn/cervical-manipulation-safety-screening","linkTitle":"Neck Manipulation Safety — Screening for Artery Problems Before You Treat"},{"id":"lq-cervical-manipulation-safety-screening-2","topic":"Manual Therapy","question":"Why is a negative neck-rotation positional test not enough?","options":["It has poor accuracy and misses most artery problems","Because it takes too long","Because it only tests the carotid artery"],"correct":0,"explanation":"Right — a negative result does not make the neck safe, so the history and examination carry the decision.","href":"/learn/cervical-manipulation-safety-screening","linkTitle":"Neck Manipulation Safety — Screening for Artery Problems Before You Treat"},{"id":"lq-choosing-balance-tests-1","topic":"Skills · Balance & Function","question":"A fit 55-year-old scores 55/56 on the Berg after an ankle injury. What is the problem with using Berg to track her recovery?","options":["The Berg is invalid after ankle injuries","A ceiling effect: she is near the top and the test cannot show further improvement; use a harder test such as the FGA or Mini-BESTest","A floor effect"],"correct":1,"explanation":"Yes — choose a test whose range fits the patient.","href":"/learn/choosing-balance-tests","linkTitle":"Choosing a Balance Test — Berg, FGA, Mini-BESTest, Four Square Step and mCTSIB"},{"id":"lq-choosing-balance-tests-2","topic":"Skills · Balance & Function","question":"A patient can stand on a firm surface with eyes open or closed, and on foam with eyes open, but falls within a few seconds on foam with eyes closed. What does the mCTSIB suggest?","options":["Reliance on vision and a vestibular or somatosensory deficit: only the vestibular system is left in condition 4, so consider a vestibular problem","A cerebellar lesion only","A normal balance system"],"correct":0,"explanation":"Yes — a fall only in condition 4 points to poor vestibular function (with vision and feet unavailable).","href":"/learn/choosing-balance-tests","linkTitle":"Choosing a Balance Test — Berg, FGA, Mini-BESTest, Four Square Step and mCTSIB"},{"id":"lq-choosing-balance-tests-3","topic":"Skills · Balance & Function","question":"Which test is best to identify the failing system in a patient with dizziness and a near-normal Berg score?","options":["The 30-second chair stand","The Mini-BESTest (or mCTSIB) because of its sensory and dynamic gait sections","Berg again"],"correct":1,"explanation":"Yes — a normal Berg may hide deficits that the harder sensory and gait items expose.","href":"/learn/choosing-balance-tests","linkTitle":"Choosing a Balance Test — Berg, FGA, Mini-BESTest, Four Square Step and mCTSIB"},{"id":"lq-clinical-reasoning-thinking-errors-1","topic":"Clinical Reasoning","question":"A therapist decides within a minute that a patient has \"just a muscle strain\" and then ignores a new finding that does not fit. Which thinking error is this?","options":["Good clinical reasoning","Anchoring and premature closure","Evidence-based practice"],"correct":1,"explanation":"Yes — holding on to the first idea and stopping the search too early.","href":"/learn/clinical-reasoning-thinking-errors","linkTitle":"Think Like an Expert — Hypotheses, Red Flags and Thinking Errors"},{"id":"lq-clinical-reasoning-thinking-errors-2","topic":"Clinical Reasoning","question":"Which of these is a red flag for serious spinal pathology?","options":["Stiffness for ten minutes in the morning","A history of cancer with new, unrelenting night pain and weight loss","Back pain that eases when walking"],"correct":1,"explanation":"Yes — this combination needs medical review before any treatment.","href":"/learn/clinical-reasoning-thinking-errors","linkTitle":"Think Like an Expert — Hypotheses, Red Flags and Thinking Errors"},{"id":"lq-clinical-reasoning-thinking-errors-3","topic":"Clinical Reasoning","question":"Why is a single red flag not always an emergency?","options":["Most have a low predictive value alone; a combination and the whole picture matter","Red flags are never important","A red flag always means cancer"],"correct":0,"explanation":"Yes — judge flags together with the history, findings and how the person looks.","href":"/learn/clinical-reasoning-thinking-errors","linkTitle":"Think Like an Expert — Hypotheses, Red Flags and Thinking Errors"},{"id":"lq-convex-concave-rule-1","topic":"Movement Science","question":"A patient lifts their arm into abduction. Which way does the humeral head glide?","options":["It doesn't glide — it only rolls","Inferior (down)","Superior (up)"],"correct":1,"explanation":"Exactly! Convex humeral head on a concave glenoid → rolls up, glides down. 🎯","href":"/learn/convex-concave-rule","linkTitle":"The Convex–Concave Rule"},{"id":"lq-convex-concave-rule-2","topic":"Movement Science","question":"Knee extension in sitting (the tibia moves on a fixed femur). Which way does the tibia glide?","options":["Anterior","Posterior"],"correct":0,"explanation":"Yes! Concave tibia on a convex femur → roll and glide in the same direction: anterior.","href":"/learn/convex-concave-rule","linkTitle":"The Convex–Concave Rule"},{"id":"lq-convex-concave-rule-3","topic":"Movement Science","question":"Viva question: a patient stands up from a squat. The convex femur moves on the fixed tibia. During this knee extension, which way does the femur glide?","options":["Anterior","Posterior"],"correct":1,"explanation":"Brilliant! You checked which bone moves. Convex femur moving → rolls anterior, glides posterior. This is exactly the thinking examiners look for.","href":"/learn/convex-concave-rule","linkTitle":"The Convex–Concave Rule"},{"id":"lq-craniosacral-therapy-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Craniosacral rhythm mean?","options":["A proposed slow rhythm in the head and spine fluids, not confirmed by research.","The triangular bone at the base of the spine.","How well different practitioners agree. For this rhythm, it is poor."],"correct":0,"explanation":"Exactly! Craniosacral rhythm — A proposed slow rhythm in the head and spine fluids, not confirmed by research.","href":"/manual-therapy/craniosacral-therapy","linkTitle":"Craniosacral Therapy"},{"id":"lq-craniosacral-therapy-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Craniosacral Therapy (or to stop and reassess)?","options":["People who want a gentle, relaxing hands-on session after screening.","Recent head injury, bleeding in the brain, aneurysm or raised pressure in the skull.","Only as an adjunct, and with honest explanation."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/craniosacral-therapy","linkTitle":"Craniosacral Therapy"},{"id":"lq-craniosacral-therapy-4","topic":"Manual Therapy · World Approaches","question":"Which evidence statement best describes craniosacral therapy for the conditions assessed in a 2024 review?","options":["It physically repositions skull bones in adults.","Strong proven benefits for all headache and spine disorders.","No convincing clinically relevant benefits were demonstrated."],"correct":2,"explanation":"The systematic review did not show clinically relevant benefit for its assessed outcomes; claims beyond the evidence should not be made.","href":"/manual-therapy/craniosacral-therapy","linkTitle":"Craniosacral Therapy"},{"id":"lq-cyriax-deep-transverse-friction-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Transverse mean?","options":["Cyriax's examination method: test resisted movements to find which tissue is hurt.","A painful, overloaded tendon, not always inflamed.","Across the fibres, at right angles to them."],"correct":2,"explanation":"Exactly! Transverse — Across the fibres, at right angles to them.","href":"/manual-therapy/cyriax-deep-transverse-friction","linkTitle":"Cyriax Deep Transverse Friction"},{"id":"lq-cyriax-deep-transverse-friction-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Cyriax Deep Transverse Friction (or to stop and reassess)?","options":["Sub-acute or persistent problems where the tissue can tolerate pressure.","Open wounds, infection, skin problems or bruising.","A well-located tendon or ligament problem with a clear tender spot, for example tennis elbow."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/cyriax-deep-transverse-friction","linkTitle":"Cyriax Deep Transverse Friction"},{"id":"lq-deep-tendon-reflexes-technique-1","topic":"Skills · Neuro Exam","question":"The right knee jerk is 3+, the left is 2+, and the right calf feels stiff. What is the best next step?","options":["Look for other UMN signs (clonus, Babinski, tone, weakness) and refer if new","Reassure — 3+ is always normal","Treat the right knee with stretching only"],"correct":0,"explanation":"Yes — an asymmetrical brisk reflex plus stiffness suggests an upper motor neuron problem, so check for clonus and the plantar response.","href":"/learn/deep-tendon-reflexes-technique","linkTitle":"Deep Tendon Reflexes — Technique, Grading and Reinforcement"},{"id":"lq-deep-tendon-reflexes-technique-2","topic":"Skills · Neuro Exam","question":"Which root level does the biceps reflex test?","options":["L3–L4","C7–C8","C5–C6"],"correct":2,"explanation":"Yes — biceps and brachioradialis are the \"5–6\" reflexes.","href":"/learn/deep-tendon-reflexes-technique","linkTitle":"Deep Tendon Reflexes — Technique, Grading and Reinforcement"},{"id":"lq-dermatomes-myotomes-reflexes-1","topic":"Neurology","question":"Weak big-toe extension and reduced sensation over the top of the foot. Which root is most likely involved?","options":["L4","S1","L5"],"correct":2,"explanation":"Yes! Great-toe extension (myotome) and dorsum of the foot (dermatome) both point to L5 — a matching pattern.","href":"/learn/dermatomes-myotomes-reflexes","linkTitle":"Dermatomes, Myotomes & Reflexes — The Neuro Screen Made Easy"},{"id":"lq-dermatomes-myotomes-reflexes-2","topic":"Neurology","question":"A reduced ankle jerk and numbness along the outer border of the foot. Which root?","options":["L5","L3","S1"],"correct":2,"explanation":"Correct — \"S1–2, buckle my shoe\". Ankle jerk + lateral foot = S1.","href":"/learn/dermatomes-myotomes-reflexes","linkTitle":"Dermatomes, Myotomes & Reflexes — The Neuro Screen Made Easy"},{"id":"lq-dermatomes-myotomes-reflexes-3","topic":"Neurology","question":"Which finding needs URGENT referral rather than routine physiotherapy?","options":["Mildly reduced sensation on one foot after lifting, stable for a week","Unilateral calf ache with a completely normal neuro screen","Saddle numbness with new difficulty passing urine"],"correct":2,"explanation":"Exactly — possible cauda equina syndrome. Same-day emergency referral.","href":"/learn/dermatomes-myotomes-reflexes","linkTitle":"Dermatomes, Myotomes & Reflexes — The Neuro Screen Made Easy"},{"id":"lq-developmental-milestones-0-5-years-1","topic":"Paediatrics","question":"A baby was born at 32 weeks (8 weeks early) and is now 6 months old by the calendar. Which milestones should you compare her with?","options":["The 9-month milestones, to be safe","The 4-month milestones (corrected age: 6 months minus about 2 months)","The 6-month milestones, because that is her real age"],"correct":1,"explanation":"Yes — until 24 months we correct for prematurity: calendar age minus the weeks born early (8 weeks is about 2 months).","href":"/learn/developmental-milestones-0-5-years","linkTitle":"Developmental Milestones 0 to 5 Years: What Is Typical, What Is a Flag"},{"id":"lq-developmental-milestones-0-5-years-2","topic":"Paediatrics","question":"A 16-month-old is not walking yet but cruises along furniture, babbles, points and plays peek-a-boo. What is the best response?","options":["Diagnose cerebral palsy because he is late","Tell the parents to buy a baby walker so he learns","Reassure, but arrange a review if he is still not walking by about 18 months, or if any skill is lost or asymmetry appears"],"correct":2,"explanation":"Yes — the WHO study found that healthy children walk alone anywhere from about 8 to 18 months. He is progressing, so this is a \"watch and review\", not an alarm.","href":"/learn/developmental-milestones-0-5-years","linkTitle":"Developmental Milestones 0 to 5 Years: What Is Typical, What Is a Flag"},{"id":"lq-developmental-milestones-0-5-years-3","topic":"Paediatrics","question":"At which age should a child typically hop on one foot?","options":["About 2 years","About 12 months","About 5 years"],"correct":2,"explanation":"Yes — hopping on one foot (a test of single-leg balance and strength) appears at the 5-year checkpoint in the CDC list.","href":"/learn/developmental-milestones-0-5-years","linkTitle":"Developmental Milestones 0 to 5 Years: What Is Typical, What Is a Flag"},{"id":"lq-end-feel-capsular-patterns-1","topic":"Clinical Reasoning","question":"You move a painful shoulder into abduction. You feel no resistance at all, but the patient begs you to stop at 60°. This end-feel is…","options":["Firm","Hard","Empty"],"correct":2,"explanation":"Yes — pain stops the movement before any resistance. Consider acute bursitis or serious pathology; don't push on.","href":"/learn/end-feel-capsular-patterns","linkTitle":"End-Feel, Capsular Patterns & Selective Tissue Tension"},{"id":"lq-end-feel-capsular-patterns-2","topic":"Clinical Reasoning","question":"A 55-year-old has a stiff shoulder: passive ER 10°, abduction 80°, IR 40°, all with an early firm end-feel. Most likely?","options":["Normal for age","Rotator cuff tear","Capsular pattern — adhesive capsulitis or glenohumeral OA"],"correct":2,"explanation":"Yes — passive loss in the order ER > ABD > IR with early firm end-feel is the shoulder capsular pattern.","href":"/learn/end-feel-capsular-patterns","linkTitle":"End-Feel, Capsular Patterns & Selective Tissue Tension"},{"id":"lq-end-feel-capsular-patterns-3","topic":"Clinical Reasoning","question":"Resisted wrist extension is strong but reproduces lateral elbow pain; passive wrist flexion with the elbow straight also hurts. Which tissue?","options":["A nerve palsy","Inert — elbow joint capsule","Contractile — common extensor tendon"],"correct":2,"explanation":"Yes — strong & painful on resistance plus pain on passive stretch the opposite way = contractile lesion (lateral elbow tendinopathy).","href":"/learn/end-feel-capsular-patterns","linkTitle":"End-Feel, Capsular Patterns & Selective Tissue Tension"},{"id":"lq-exercise-dosage-1","topic":"Exercise Prescription","question":"Your patient finishes a set of squats and says they could have done about 2 more reps with good form. What's their RIR?","options":["12","0","2"],"correct":2,"explanation":"Yes — 2 reps in reserve. For most strength goals, ending sets at about 1–3 RIR is a good, safe target.","href":"/learn/exercise-dosage","linkTitle":"Exercise Dosage — FITT, RPE & Reps in Reserve"},{"id":"lq-exercise-dosage-2","topic":"Exercise Prescription","question":"Your COPD patient is walking on a treadmill for aerobic training. Which response tells you they're at a MODERATE intensity?","options":["\"I could sing along to the radio.\"","\"I can only manage a word or two.\"","\"I can talk in sentences, but I couldn't sing.\""],"correct":2,"explanation":"Exactly — the talk test's moderate zone, about RPE 12–13. (In lung disease, also watch breathlessness and SpO₂ as your service protocol directs.)","href":"/learn/exercise-dosage","linkTitle":"Exercise Dosage — FITT, RPE & Reps in Reserve"},{"id":"lq-exercise-dosage-3","topic":"Exercise Prescription","question":"A knee OA patient does 3 × 10 sit-to-stands easily, no pain, RPE 9/20. Best next step?","options":["Increase sets, reps and load all at once","Progress one variable — e.g. a lower chair or holding a weight","Keep the same dose for three more months"],"correct":1,"explanation":"Exactly — one change, then see how the knee responds over the next 24 hours.","href":"/learn/exercise-dosage","linkTitle":"Exercise Dosage — FITT, RPE & Reps in Reserve"},{"id":"lq-exercise-intensity-borg-talk-test-1","topic":"Skills · Vitals & Monitoring","question":"A patient on a beta-blocker has a heart rate of 90 during brisk walking but feels it is \"hard\" (RPE 15) and is breathless. How should you set intensity?","options":["Use RPE and the talk test (aim for 11–14 and speaking in short sentences), not the heart-rate target","Ignore symptoms and follow the monitor","Increase the speed until the heart rate reaches 70% of age-predicted maximum"],"correct":0,"explanation":"Yes — beta-blockers blunt the heart-rate response, so percentage-of-maximum targets are unreliable.","href":"/learn/exercise-intensity-borg-talk-test","linkTitle":"Exercise Intensity — Borg RPE, Breathlessness Scale, Talk Test and Heart-Rate Reserve"},{"id":"lq-exercise-intensity-borg-talk-test-2","topic":"Skills · Vitals & Monitoring","question":"Which statement about the talk test is correct for moderate intensity?","options":["The patient cannot speak at all","The patient can sing comfortably","The patient can talk but not sing; they speak in short sentences"],"correct":2,"explanation":"Yes — full sentences with singing is light; only a few words is too hard.","href":"/learn/exercise-intensity-borg-talk-test","linkTitle":"Exercise Intensity — Borg RPE, Breathlessness Scale, Talk Test and Heart-Rate Reserve"},{"id":"lq-exercise-intensity-borg-talk-test-3","topic":"Skills · Vitals & Monitoring","question":"Which tool is best to separate breathing effort from leg effort in a lung patient?","options":["The 6–20 Borg RPE alone","The modified Borg CR10 breathlessness scale","Resting heart rate"],"correct":1,"explanation":"Yes — it asks specifically about breathlessness.","href":"/learn/exercise-intensity-borg-talk-test","linkTitle":"Exercise Intensity — Borg RPE, Breathlessness Scale, Talk Test and Heart-Rate Reserve"},{"id":"lq-exercise-stop-signs-and-ward-mobilisation-1","topic":"Skills · Vitals & Monitoring","question":"During a treadmill session a patient's systolic pressure drops from 150 to 120 as the speed increases, and they feel light-headed. What do you do?","options":["Stop, sit the patient down, check pulse, BP and symptoms, and inform the medical team","Encourage the patient to push through","Slow down slightly and carry on"],"correct":0,"explanation":"Yes — a systolic fall with increasing workload is a stop sign (possible heart failure, arrhythmia or outflow obstruction).","href":"/learn/exercise-stop-signs-and-ward-mobilisation","linkTitle":"When to Stop — Exercise Stop Signs and Early Mobilisation on the Ward and ICU"},{"id":"lq-exercise-stop-signs-and-ward-mobilisation-2","topic":"Skills · Vitals & Monitoring","question":"Why use a track-and-trigger score such as NEWS2 on the ward?","options":["To decide the exercise prescription","It combines respiratory rate, SpO₂, blood pressure, pulse, temperature and alertness into one score that flags deterioration early","To replace clinical judgement"],"correct":1,"explanation":"Yes — a rising score tells you to escalate before the patient crashes.","href":"/learn/exercise-stop-signs-and-ward-mobilisation","linkTitle":"When to Stop — Exercise Stop Signs and Early Mobilisation on the Ward and ICU"},{"id":"lq-exercise-stop-signs-and-ward-mobilisation-3","topic":"Skills · Vitals & Monitoring","question":"Which of these is a red (do not mobilise until reviewed) finding?","options":["Mild soreness after yesterday's walk","SpO₂ 95 % and a heart rate of 80","New chest pain with a resting heart rate over 130"],"correct":2,"explanation":"Yes — new chest pain with a fast rate needs medical review before activity.","href":"/learn/exercise-stop-signs-and-ward-mobilisation","linkTitle":"When to Stop — Exercise Stop Signs and Early Mobilisation on the Ward and ICU"},{"id":"lq-explaining-manual-therapy-effects-1","topic":"Pain Science","question":"A patient asks, \"Did you put my bone back in place?\" What is the most honest reply?","options":["\"Yes, your bone was out of place.\"","\"It doesn't matter, just lie down.\"","\"Your joint was stiff and sore; the treatment calms the pain and lets it move more easily, and exercise helps keep that.\""],"correct":2,"explanation":"Yes — it is accurate, calm and points to exercise.","href":"/learn/explaining-manual-therapy-effects","linkTitle":"What Manual Therapy Really Does — And How to Explain It to Patients"},{"id":"lq-explaining-manual-therapy-effects-2","topic":"Pain Science","question":"What does the neurophysiological model say manual therapy mainly changes?","options":["The length of the ligaments permanently","The position of the bones","How the nervous system processes pain and movement"],"correct":2,"explanation":"Yes — the effect is mainly through the nervous system and context, not by repositioning a bone.","href":"/learn/explaining-manual-therapy-effects","linkTitle":"What Manual Therapy Really Does — And How to Explain It to Patients"},{"id":"lq-explaining-manual-therapy-effects-3","topic":"Pain Science","question":"Why add an exercise right after a manual technique?","options":["Because exercise removes the effect of the technique","Because pain is lower and movement is easier for a short while, so the change can be used and held","Because the patient can pay less"],"correct":1,"explanation":"Yes — the window is short, so use it.","href":"/learn/explaining-manual-therapy-effects","linkTitle":"What Manual Therapy Really Does — And How to Explain It to Patients"},{"id":"lq-facilitated-positional-release-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Neutral mean?","options":["The direction in which the tissue feels loosest.","The position with the least tension in the area.","A light compression added to the neutral position."],"correct":1,"explanation":"Exactly! Neutral — The position with the least tension in the area.","href":"/manual-therapy/facilitated-positional-release","linkTitle":"Facilitated Positional Release (FPR)"},{"id":"lq-facilitated-positional-release-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Facilitated Positional Release (FPR) (or to stop and reassess)?","options":["Fracture, instability or unexplained severe pain.","Tight, tender muscle areas that are sensitive to firm treatment.","Neck and back muscle tension as part of a larger plan."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/facilitated-positional-release","linkTitle":"Facilitated Positional Release (FPR)"},{"id":"lq-falls-prevention-older-adults-1","topic":"Geriatrics","question":"Which exercise approach has the strongest evidence for reducing falls?","options":["Regular balance and functional strength exercise, three or more times a week","Gentle stretching only","Rest and avoiding activity"],"correct":0,"explanation":"Yes — challenging balance and leg-strength exercise reduces falls by about a quarter.","href":"/learn/falls-prevention-older-adults","linkTitle":"Preventing Falls in Older Adults — Screen, Strengthen, Balance"},{"id":"lq-falls-prevention-older-adults-2","topic":"Geriatrics","question":"A patient takes 18 seconds on the timed up and go and has fallen twice this year. What is the best next step?","options":["Reassure that falls are a normal part of ageing","Advise staying seated most of the day","Start a supervised balance and strength programme and review medicines and the home"],"correct":2,"explanation":"Yes — this person has a clear fall risk and benefits from exercise and risk review.","href":"/learn/falls-prevention-older-adults","linkTitle":"Preventing Falls in Older Adults — Screen, Strengthen, Balance"},{"id":"lq-falls-prevention-older-adults-3","topic":"Geriatrics","question":"Which finding after a fall needs urgent medical review?","options":["Mild muscle ache next day","A small bruise on the shin","A blow to the head with drowsiness, vomiting or a severe headache"],"correct":2,"explanation":"Yes — these may signal a head injury or bleeding.","href":"/learn/falls-prevention-older-adults","linkTitle":"Preventing Falls in Older Adults — Screen, Strengthen, Balance"},{"id":"lq-fascial-distortion-model-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Fascial distortion mean?","options":["A proposed small bulge of tissue through a fascial layer.","The model's term for a proposed twist, fold or tension in connective tissue.","A line of tight fascia, often shown by tracing a line along the body."],"correct":1,"explanation":"Exactly! Fascial distortion — The model's term for a proposed twist, fold or tension in connective tissue.","href":"/manual-therapy/fascial-distortion-model","linkTitle":"Fascial Distortion Model (FDM)"},{"id":"lq-fascial-distortion-model-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Fascial Distortion Model (FDM) (or to stop and reassess)?","options":["As a way to organize patient descriptions of pain.","Fractures, infection, bleeding disorders or red flags.","Practitioners trained in the model, where the patient understands and consents to firm techniques."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/fascial-distortion-model","linkTitle":"Fascial Distortion Model (FDM)"},{"id":"lq-fascial-distortion-model-4","topic":"Manual Therapy · World Approaches","question":"A patient traces a long painful line with one finger. What should you infer?","options":["The gesture may guide inquiry but cannot confirm tissue pathology.","A specific fascial distortion is definitely present.","The gesture is irrelevant to the interview."],"correct":0,"explanation":"Patient gesture can be useful symptom information; it does not validate an unverified tissue mechanism or replace screening.","href":"/manual-therapy/fascial-distortion-model","linkTitle":"Fascial Distortion Model (FDM)"},{"id":"lq-fascial-manipulation-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Fascial segment mean?","options":["A region of connected fascia and muscles responsible for a movement direction.","A point linked to the patient's perceived pain.","A point believed to coordinate muscle fibres within a segment."],"correct":0,"explanation":"Exactly! Fascial segment — A region of connected fascia and muscles responsible for a movement direction.","href":"/manual-therapy/fascial-manipulation","linkTitle":"Fascial Manipulation"},{"id":"lq-fascial-manipulation-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Fascial Manipulation (or to stop and reassess)?","options":["Infection, wounds, tumours or fresh injury.","Practitioners trained in the method.","Persistent musculoskeletal pain where movement patterns are not explained by one local area."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/fascial-manipulation","linkTitle":"Fascial Manipulation"},{"id":"lq-gait-cycle-1","topic":"Movement Science","question":"At normal walking speed, roughly what percentage of the cycle is spent in stance?","options":["About 40%","About 80%","About 60%"],"correct":2,"explanation":"Right — about 60% stance, 40% swing.","href":"/learn/gait-cycle","linkTitle":"The Gait Cycle Made Easy"},{"id":"lq-gait-cycle-2","topic":"Movement Science","question":"A patient's foot slaps down loudly just after heel strike. Which muscle group is likely weak?","options":["Hamstrings","Plantarflexors (calf)","Dorsiflexors (tibialis anterior)"],"correct":2,"explanation":"Yes — they normally lower the foot eccentrically in loading response. Weak dorsiflexors → foot slap.","href":"/learn/gait-cycle","linkTitle":"The Gait Cycle Made Easy"},{"id":"lq-gait-cycle-3","topic":"Movement Science","question":"While standing on the RIGHT leg, the patient's LEFT side of the pelvis drops. Which muscle is weak?","options":["Right hip abductors (gluteus medius)","Left hip abductors","Right quadriceps"],"correct":0,"explanation":"Correct — a positive Trendelenburg sign points to weakness on the STANCE side. The right abductors should hold the pelvis level.","href":"/learn/gait-cycle","linkTitle":"The Gait Cycle Made Easy"},{"id":"lq-goniometry-foundations-1","topic":"Skills · Measurement","question":"Which part of the goniometer matters most for an accurate reading?","options":["Putting the axis exactly on the joint line","Using the biggest goniometer available","Aligning the two arms along the bony landmarks"],"correct":2,"explanation":"Yes — the axis is only an approximation of the moving axis; when the arms follow the bones, the axis falls where it should.","href":"/learn/goniometry-foundations","linkTitle":"Goniometry Foundations — Axis, Arms, Scale and the Six Steps"},{"id":"lq-goniometry-foundations-2","topic":"Skills · Measurement","question":"When recording hip flexion, the dial reads 130°, but the patient's pelvis tilted backwards during the movement. What should you do?","options":["Stabilise the pelvis and re-measure; the 130° includes false range","Record the average of the two sides","Record 130° because the dial says so"],"correct":0,"explanation":"Yes — substitution inflates the number. A true reading needs the pelvis held still.","href":"/learn/goniometry-foundations","linkTitle":"Goniometry Foundations — Axis, Arms, Scale and the Six Steps"},{"id":"lq-goniometry-foundations-3","topic":"Skills · Measurement","question":"Which statement about normal range of motion values is correct?","options":["They are guides that change with age, sex and the reference book; the other side is often the best \"normal\"","They are exact and the same for everyone","A value below the table is always a disease"],"correct":0,"explanation":"Yes — compare with the patient's own other side and with function, not just with a table.","href":"/learn/goniometry-foundations","linkTitle":"Goniometry Foundations — Axis, Arms, Scale and the Six Steps"},{"id":"lq-goniometry-lower-limb-1","topic":"Skills · Measurement","question":"Why is the knee allowed to bend during hip flexion measurement?","options":["To protect the knee joint","To slacken the hamstrings so they do not limit the joint range","To make the goniometer easier to read"],"correct":1,"explanation":"Yes — a straight knee would stop the hip at about 80° because of hamstring length, not the hip joint.","href":"/learn/goniometry-lower-limb","linkTitle":"Goniometry of the Hip, Knee and Ankle — Positions That Make It Fair"},{"id":"lq-goniometry-lower-limb-2","topic":"Skills · Measurement","question":"Dorsiflexion is 5° with the knee straight and 18° with the knee bent. What does this suggest?","options":["A normal ankle with no problem","A stiff ankle joint capsule","Tight gastrocnemius (a muscle-length problem); the ankle joint range is fine"],"correct":2,"explanation":"Yes — the range returns when the gastrocnemius is slackened, so the muscle, not the joint, is the limit.","href":"/learn/goniometry-lower-limb","linkTitle":"Goniometry of the Hip, Knee and Ankle — Positions That Make It Fair"},{"id":"lq-goniometry-lower-limb-3","topic":"Skills · Measurement","question":"Which landmark is the axis for knee flexion?","options":["The lateral epicondyle of the femur","The patella","The greater trochanter"],"correct":0,"explanation":"Yes — the joint's axis is approximately through the lateral epicondyle.","href":"/learn/goniometry-lower-limb","linkTitle":"Goniometry of the Hip, Knee and Ankle — Positions That Make It Fair"},{"id":"lq-goniometry-upper-limb-1","topic":"Skills · Measurement","question":"A patient's shoulder flexion reads 180°, but the lumbar spine arched off the plinth during the movement. What is the best action?","options":["Record 180° because it matches the normal value","Re-measure with the knees flexed and the back flat; the arch added false range","Stop measuring the shoulder"],"correct":1,"explanation":"Yes — flexing the hips and knees flattens the lumbar spine and removes a classic substitution.","href":"/learn/goniometry-upper-limb","linkTitle":"Goniometry of the Shoulder, Elbow and Wrist — Landmarks That Work"},{"id":"lq-goniometry-upper-limb-2","topic":"Skills · Measurement","question":"Why must the palm face up in shoulder abduction?","options":["To externally rotate the humerus so the greater tubercle clears the acromion","To keep the elbow straight","To make the goniometer easier to read"],"correct":0,"explanation":"Yes — otherwise the tubercle blocks the movement at about 90°.","href":"/learn/goniometry-upper-limb","linkTitle":"Goniometry of the Shoulder, Elbow and Wrist — Landmarks That Work"},{"id":"lq-goniometry-upper-limb-3","topic":"Skills · Measurement","question":"Which sequence is the capsular pattern of the shoulder?","options":["Flexion, then extension, then rotation","External rotation, then abduction, then internal rotation","Internal rotation, then flexion, then external rotation"],"correct":1,"explanation":"Yes — that order of loss is Cyriax's capsular pattern for the glenohumeral joint.","href":"/learn/goniometry-upper-limb","linkTitle":"Goniometry of the Shoulder, Elbow and Wrist — Landmarks That Work"},{"id":"lq-heat-and-cold-therapy-evidence-1","topic":"Electrotherapy","question":"Which problem suits heat the best?","options":["A stiff, tight lower back with no swelling or fever","A hot, swollen, red joint","A new, bleeding wound"],"correct":0,"explanation":"Yes — heat relaxes muscle and eases stiffness.","href":"/learn/heat-and-cold-therapy-evidence","linkTitle":"Heat and Cold — What They Really Do and When to Avoid Them"},{"id":"lq-heat-and-cold-therapy-evidence-2","topic":"Electrotherapy","question":"What does the PEACE and LOVE approach suggest for early soft-tissue injury?","options":["Heat and deep massage on day one","Protect, elevate, avoid anti-inflammatories, compress and educate; then load, stay optimistic, build blood flow with exercise and restore movement","Ice for two days and complete rest for a month"],"correct":1,"explanation":"Yes — it focuses on protection first and then early, progressive loading.","href":"/learn/heat-and-cold-therapy-evidence","linkTitle":"Heat and Cold — What They Really Do and When to Avoid Them"},{"id":"lq-heat-and-cold-therapy-evidence-3","topic":"Electrotherapy","question":"When must you avoid both heat and cold?","options":["On a muscle that is a little stiff","Over skin with poor sensation or poor circulation","After a hard training session"],"correct":1,"explanation":"Yes — the person cannot feel damage starting.","href":"/learn/heat-and-cold-therapy-evidence","linkTitle":"Heat and Cold — What They Really Do and When to Avoid Them"},{"id":"lq-high-velocity-low-amplitude-thrust-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does Thrust / manipulation mean?","options":["Positioning the joint to its end of range so only a small thrust is needed.","The popping sound, likely from gas changes inside the joint. It is not proof of a good result.","A fast, small-amplitude movement at the end of range."],"correct":2,"explanation":"Exactly! Thrust / manipulation — A fast, small-amplitude movement at the end of range.","href":"/manual-therapy/high-velocity-low-amplitude-thrust","linkTitle":"HVLA Thrust Manipulation"},{"id":"lq-high-velocity-low-amplitude-thrust-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use HVLA Thrust Manipulation (or to stop and reassess)?","options":["Fracture, osteoporosis, infection, cancer, spinal instability or inflammatory spine disease.","Mechanical back or thoracic pain with local stiffness and no red flags, when the patient agrees and you are trained.","Short-duration low back pain with no pain below the knee (as one example, based on prediction rules that have had mixed results in later studies)."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/high-velocity-low-amplitude-thrust","linkTitle":"HVLA Thrust Manipulation"},{"id":"lq-hip-groin-pain-examination-1","topic":"Skills · Measurement","question":"A patient has groin pain and a negative FADIR test. What does this most reasonably tell you?","options":["Femoroacetabular impingement or a labral tear is unlikely","A stress fracture is certain","The hip joint is proven healthy"],"correct":0,"explanation":"Yes — FADIR is very sensitive, so a negative result makes these problems less likely.","href":"/learn/hip-groin-pain-examination","linkTitle":"Hip and Groin Pain — What to Test, What to Rule Out"},{"id":"lq-hip-groin-pain-examination-2","topic":"Skills · Measurement","question":"Which finding should make you suspect a femoral neck stress fracture?","options":["Groin pain after a sudden rise in running, with pain on hopping and at night","Pain on the outer hip when lying on that side only","Tight hamstrings after sitting"],"correct":0,"explanation":"Yes — load-related deep groin pain with night pain needs imaging before loading.","href":"/learn/hip-groin-pain-examination","linkTitle":"Hip and Groin Pain — What to Test, What to Rule Out"},{"id":"lq-hip-groin-pain-examination-3","topic":"Skills · Measurement","question":"A 13-year-old with a limp has knee pain and a stiff, externally rotated hip. What is the safest action?","options":["Stop weight-bearing and refer urgently for imaging","Reassure and review in a month","Give knee strengthening exercises"],"correct":0,"explanation":"Yes — a slipped capital femoral epiphysis can look like knee pain and needs urgent care.","href":"/learn/hip-groin-pain-examination","linkTitle":"Hip and Groin Pain — What to Test, What to Rule Out"},{"id":"lq-iastm-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Scanning mean?","options":["The angle between tool and skin, often 30-60 degrees.","Gentle strokes to find rough or tender areas.","Small red spots from tiny blood vessel leaks. They can occur but are not a goal."],"correct":1,"explanation":"Exactly! Scanning — Gentle strokes to find rough or tender areas.","href":"/manual-therapy/iastm","linkTitle":"Instrument-Assisted Soft-Tissue Mobilization (IASTM)"},{"id":"lq-iastm-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Instrument-Assisted Soft-Tissue Mobilization (IASTM) (or to stop and reassess)?","options":["Persistent tendon or muscle tightness where hands-on soft-tissue work is suitable.","Open wounds, skin disease, infection, deep vein thrombosis or fragile skin.","As an adjunct before exercise."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/iastm","linkTitle":"Instrument-Assisted Soft-Tissue Mobilization (IASTM)"},{"id":"lq-janda-crossed-syndromes-1","topic":"Skills · Posture & Palpation","question":"A desk worker has forward head, rounded shoulders and tight pectorals. Which muscles are most likely weak?","options":["Deep neck flexors, lower trapezius and serratus anterior","Upper trapezius and levator scapulae","Pectoralis major and minor"],"correct":0,"explanation":"Yes — that is the upper crossed pattern: tight front, weak back. Treat both sides of the cross.","href":"/learn/janda-crossed-syndromes","linkTitle":"Janda's Crossed Syndromes and Kendall's Postures — Tight, Weak and What To Do"},{"id":"lq-janda-crossed-syndromes-2","topic":"Skills · Posture & Palpation","question":"In which posture do the hamstrings and upper abdominals tend to be strong and short, while the hip flexors are weak?","options":["Kypho-lordotic posture","Upper crossed syndrome","Sway-back posture"],"correct":2,"explanation":"Yes — the pelvis shifts forward and the hips hang in extension on strong hamstrings; it is the opposite of the lower crossed pattern.","href":"/learn/janda-crossed-syndromes","linkTitle":"Janda's Crossed Syndromes and Kendall's Postures — Tight, Weak and What To Do"},{"id":"lq-janda-crossed-syndromes-3","topic":"Skills · Posture & Palpation","question":"What is the best evidence-based attitude toward the crossed-syndrome model?","options":["Use it as a hypothesis, test the muscles in the patient and treat measurable deficits","Apply it to every patient with poor posture","Ignore it entirely"],"correct":0,"explanation":"Yes — it guides your examination but does not replace it.","href":"/learn/janda-crossed-syndromes","linkTitle":"Janda's Crossed Syndromes and Kendall's Postures — Tight, Weak and What To Do"},{"id":"lq-kaltenborn-evjenth-mobilization-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does Convex / concave mean?","options":["Convex is rounded outward like a ball; concave is curved inward like a cup.","An imaginary flat plane across the concave joint surface. Gliding runs parallel to it and traction runs at right angles to it.","The free play in tissues before they begin to tighten."],"correct":0,"explanation":"Exactly! Convex / concave — Convex is rounded outward like a ball; concave is curved inward like a cup.","href":"/manual-therapy/kaltenborn-evjenth-mobilization","linkTitle":"Kaltenborn–Evjenth Mobilization"},{"id":"lq-kaltenborn-evjenth-mobilization-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use Kaltenborn–Evjenth Mobilization (or to stop and reassess)?","options":["When you need to decide glide direction logically, for example for shoulder elevation or knee extension.","A joint that moves less than the other side with a firm, capsular-type end-feel.","Unstable joints, acute fractures, active infection or inflammation, and suspected tumour."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/kaltenborn-evjenth-mobilization","linkTitle":"Kaltenborn–Evjenth Mobilization"},{"id":"lq-knee-ligament-meniscus-exam-1","topic":"Skills · Measurement","question":"Which test is the best single clinical test for an ACL rupture?","options":["The McMurray test","The Lachman test","The patellar tap"],"correct":1,"explanation":"Yes — it is more accurate than the anterior drawer, especially when the knee is swollen.","href":"/learn/knee-ligament-meniscus-exam","linkTitle":"The Injured Knee — A Step-by-Step Ligament and Meniscus Examination"},{"id":"lq-knee-ligament-meniscus-exam-2","topic":"Skills · Measurement","question":"Valgus laxity at 0° and at 30° with no firm end-point after a ski fall suggests what?","options":["A minor meniscus strain","A severe MCL injury, likely with cruciate or capsule involvement; refer","A normal knee"],"correct":1,"explanation":"Yes — laxity when straight means more than the MCL is injured.","href":"/learn/knee-ligament-meniscus-exam","linkTitle":"The Injured Knee — A Step-by-Step Ligament and Meniscus Examination"},{"id":"lq-knee-ligament-meniscus-exam-3","topic":"Skills · Measurement","question":"A knee will not straighten fully after a twist and feels as if something is blocking it. What do you suspect?","options":["A locked knee from a displaced meniscus tear, which needs early referral","A simple muscle strain","A normal finding in a swollen knee"],"correct":0,"explanation":"Yes — a mechanical block to extension is a reason for early specialist review.","href":"/learn/knee-ligament-meniscus-exam","linkTitle":"The Injured Knee — A Step-by-Step Ligament and Meniscus Examination"},{"id":"lq-leg-nerve-injuries-1","topic":"Skills · Neuro Exam","question":"A woman has a new foot drop after a long hospital stay with her legs crossed in bed. Dorsiflexion and eversion are weak, but inversion and hip abduction are normal, with numbness over the top of the foot and outer shin. Which nerve?","options":["L5 nerve root","Tibial nerve","Common fibular nerve at the fibular neck"],"correct":2,"explanation":"Yes — normal inversion and hip abduction rule out the L5 root. Remove the pressure, protect with an ankle-foot orthosis if needed and reassess.","href":"/learn/leg-nerve-injuries","linkTitle":"Leg Nerve Injuries — Femoral, Sciatic, Fibular, Tibial and Gluteal"},{"id":"lq-leg-nerve-injuries-2","topic":"Skills · Neuro Exam","question":"A patient cannot stand on tiptoe on the left leg and has a numb sole. Which nerve division is mainly affected?","options":["Tibial nerve (S1–S2 plantarflexors)","Common fibular nerve","Femoral nerve"],"correct":0,"explanation":"Yes — plantarflexion and the plantar skin both depend on the tibial nerve.","href":"/learn/leg-nerve-injuries","linkTitle":"Leg Nerve Injuries — Femoral, Sciatic, Fibular, Tibial and Gluteal"},{"id":"lq-leg-nerve-injuries-3","topic":"Skills · Neuro Exam","question":"Standing on the right leg, a patient's left pelvis drops. Which structure is weak?","options":["Left gluteus medius","Right gluteus medius (superior gluteal nerve or L5 root)","Right quadriceps"],"correct":1,"explanation":"Yes — the stance-side abductors hold the pelvis level; when they fail the opposite side drops.","href":"/learn/leg-nerve-injuries","linkTitle":"Leg Nerve Injuries — Femoral, Sciatic, Fibular, Tibial and Gluteal"},{"id":"lq-levers-torque-1","topic":"Movement Science","question":"A 2 kg weight is held in the hand 30 cm from the elbow axis, forearm horizontal. Roughly what torque does it create? (Use 10 N per kg.)","options":["0.6 Nm","60 Nm","6 Nm"],"correct":2,"explanation":"Yes: 20 N × 0.3 m = 6 Nm — and the biceps, with its tiny moment arm, must make far more force than 20 N to match it.","href":"/learn/levers-torque","linkTitle":"Levers, Torque & Moment Arms — Biomechanics You Actually Use"},{"id":"lq-levers-torque-2","topic":"Movement Science","question":"A patient with right hip OA asks which hand to hold the walking stick in. Best advice?","options":["Left hand, moving the stick with the right leg","Either hand — it makes no difference","Right hand, next to the painful hip"],"correct":0,"explanation":"Yes — opposite hand, advanced with the painful leg. The long counter-moment reduces abductor force and hip compression.","href":"/learn/levers-torque","linkTitle":"Levers, Torque & Moment Arms — Biomechanics You Actually Use"},{"id":"lq-levers-torque-3","topic":"Movement Science","question":"When the biceps flexes the elbow to lift a cup, what lever class is it?","options":["1st class","3rd class","2nd class"],"correct":1,"explanation":"Yes — axis (elbow), then effort (biceps insertion), then load (cup in the hand). Great for speed and range, costly in force.","href":"/learn/levers-torque","linkTitle":"Levers, Torque & Moment Arms — Biomechanics You Actually Use"},{"id":"lq-limb-length-and-girth-1","topic":"Skills · Measurement","question":"True leg lengths are equal, but apparent length is 2 cm shorter on the left. What does this suggest?","options":["A functional discrepancy, for example a pelvic tilt or hip contracture, not a short bone","A short femur","A short tibia"],"correct":0,"explanation":"Yes — equal true length with unequal apparent length points to the pelvis or hip, so look at pelvic tilt, scoliosis and hip adduction contracture.","href":"/learn/limb-length-and-girth","linkTitle":"Limb Length and Girth — True, Apparent and Functional Leg Length, Swelling and Wasting"},{"id":"lq-limb-length-and-girth-3","topic":"Skills · Measurement","question":"Which landmark is the starting point of true leg length?","options":["The umbilicus","The greater trochanter","The ASIS"],"correct":2,"explanation":"Yes — true length runs from the ASIS to the medial malleolus.","href":"/learn/limb-length-and-girth","linkTitle":"Limb Length and Girth — True, Apparent and Functional Leg Length, Swelling and Wasting"},{"id":"lq-maitland-grades-1","topic":"Manual Therapy","question":"Which grade is a LARGE amplitude movement that goes INTO resistance, up to the limit?","options":["Grade III","Grade IV","Grade II"],"correct":0,"explanation":"Correct! Large amplitude, into resistance, up to the limit = Grade III.","href":"/learn/maitland-grades","linkTitle":"Maitland Grades I–V, Made Visual"},{"id":"lq-maitland-grades-2","topic":"Manual Therapy","question":"A frozen shoulder: very stiff, only mild pain, not irritable. Which grades fit best?","options":["Grades III–IV","Grade V only","Grades I–II"],"correct":0,"explanation":"Yes! Stiffness-dominant → work into resistance with III–IV, then reassess range after each set.","href":"/learn/maitland-grades","linkTitle":"Maitland Grades I–V, Made Visual"},{"id":"lq-maitland-grades-3","topic":"Manual Therapy","question":"Examiner: \"What exactly separates Grade II from Grade III?\"","options":["Whether the movement enters resistance","The speed of the movement","The amount of force"],"correct":0,"explanation":"Perfect answer. Both are large amplitude — Grade III goes into resistance, Grade II doesn't.","href":"/learn/maitland-grades","linkTitle":"Maitland Grades I–V, Made Visual"},{"id":"lq-maitland-joint-mobilization-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does Comparable sign mean?","options":["The one movement or symptom you test before and after treatment, for example neck rotation to the right or shoulder lifting to 90 degrees.","A tiny joint glide the patient cannot do on their own, such as one vertebra gliding forward. You produce it with your hands.","How easily symptoms flare, how bad they get, and how long they take to settle. High irritability means be gentle."],"correct":0,"explanation":"Exactly! Comparable sign — The one movement or symptom you test before and after treatment, for example neck rotation to the right or shoulder lifting to 90 degrees.","href":"/manual-therapy/maitland-joint-mobilization","linkTitle":"Maitland Joint Mobilization"},{"id":"lq-maitland-joint-mobilization-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use Maitland Joint Mobilization (or to stop and reassess)?","options":["Unstable fracture, dislocation, active infection, or suspected cancer in the area.","A painful, stiff joint where one movement clearly reproduces the patient's pain (positive comparable sign).","Pain-dominant, irritable joints (use Grades I-II) or stiffness-dominant, calmer joints (use Grades III-IV)."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/maitland-joint-mobilization","linkTitle":"Maitland Joint Mobilization"},{"id":"lq-manual-lymphatic-drainage-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Lymphedema mean?","options":["The area at the base of the neck where lymph drains into the bloodstream.","A small filter station for lymph fluid (neck, armpit, groin).","Swelling caused by lymph fluid not draining properly."],"correct":2,"explanation":"Exactly! Lymphedema — Swelling caused by lymph fluid not draining properly.","href":"/manual-therapy/manual-lymphatic-drainage","linkTitle":"Manual Lymphatic Drainage"},{"id":"lq-manual-lymphatic-drainage-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Manual Lymphatic Drainage (or to stop and reassess)?","options":["Swelling after some surgeries when cleared by the medical team.","Lymphedema, usually with medical guidance.","Acute infection, such as cellulitis, or acute blood clot."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/manual-lymphatic-drainage","linkTitle":"Manual Lymphatic Drainage"},{"id":"lq-manual-traction-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does Distraction mean?","options":["The joint position where tissues are most relaxed and the joint has most room.","Separating two joint surfaces by pulling them directly apart.","Pulling along the length of the limb, for example pulling the arm away from the shoulder."],"correct":1,"explanation":"Exactly! Distraction — Separating two joint surfaces by pulling them directly apart.","href":"/manual-therapy/manual-traction","linkTitle":"Manual Traction & Joint Distraction"},{"id":"lq-manual-traction-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use Manual Traction & Joint Distraction (or to stop and reassess)?","options":["Joint pain that eases when compression is removed.","Neck or arm pain with a positive response to gentle traction, as one part of a plan.","Instability, fracture, infection, or rheumatoid involvement of the upper neck."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/manual-traction","linkTitle":"Manual Traction & Joint Distraction"},{"id":"lq-mckenzie-mdt-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Centralization mean?","options":["Symptoms moving farther down the limb.","A movement direction that consistently reduces symptoms.","Pain or symptoms moving from the limb back toward the spine."],"correct":2,"explanation":"Exactly! Centralization — Pain or symptoms moving from the limb back toward the spine.","href":"/manual-therapy/mckenzie-mdt","linkTitle":"McKenzie Method — Mechanical Diagnosis & Therapy (MDT)"},{"id":"lq-mckenzie-mdt-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use McKenzie Method — Mechanical Diagnosis & Therapy (MDT) (or to stop and reassess)?","options":["Red flags: progressive weakness, loss of bowel or bladder control, saddle numbness, major trauma or systemic illness.","When you want the patient to take charge of treatment.","Back or neck pain, with or without arm or leg pain, with no red flags."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/mckenzie-mdt","linkTitle":"McKenzie Method — Mechanical Diagnosis & Therapy (MDT)"},{"id":"lq-mckenzie-mdt-4","topic":"Manual Therapy · World Approaches","question":"What best captures MDT's distinguishing feature?","options":["Give lumbar extension to every back-pain patient.","Classify and tailor care to repeated-movement response.","Use manual thrusts as the main treatment."],"correct":1,"explanation":"MDT is an assessment-led, active, self-management approach; direction and classification depend on each person's response.","href":"/manual-therapy/mckenzie-mdt","linkTitle":"McKenzie Method — Mechanical Diagnosis & Therapy (MDT)"},{"id":"lq-mennell-joint-play-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Joint play mean?","options":["The joint position with the least play, most stable.","Small passive movements of joint surfaces.","The joint position with the most room for joint play."],"correct":1,"explanation":"Exactly! Joint play — Small passive movements of joint surfaces.","href":"/manual-therapy/mennell-joint-play","linkTitle":"Mennell Joint-Play Approach"},{"id":"lq-mennell-joint-play-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Mennell Joint-Play Approach (or to stop and reassess)?","options":["A joint with restricted movement and no clear tissue cause.","Fractures, infection, or instability.","As part of an orthopedic examination."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/mennell-joint-play","linkTitle":"Mennell Joint-Play Approach"},{"id":"lq-mmt-grading-0-to-5-1","topic":"Skills · Measurement","question":"A patient cannot lift the arm against gravity but can move it fully when it rests on a smooth board. What is the grade?","options":["Grade 1","Grade 3","Grade 2"],"correct":2,"explanation":"Yes — full range with gravity eliminated is grade 2. Grade 3 needs full range against gravity.","href":"/learn/mmt-grading-0-to-5","linkTitle":"Manual Muscle Testing — The 0 to 5 Scale Without Guesswork"},{"id":"lq-mmt-grading-0-to-5-2","topic":"Skills · Measurement","question":"Where should you apply resistance when testing a muscle?","options":["At the distal end of the segment that the muscle moves, building slowly over 2–3 seconds","Over the joint that is moving","In the middle of the segment, with a quick push"],"correct":0,"explanation":"Yes — the distal end gives the longest lever, so the force is graded and reproducible.","href":"/learn/mmt-grading-0-to-5","linkTitle":"Manual Muscle Testing — The 0 to 5 Scale Without Guesswork"},{"id":"lq-mmt-grading-0-to-5-3","topic":"Skills · Measurement","question":"Which grade can a handheld dynamometer help you separate that MMT often cannot?","options":["4 versus 5 (mild to moderate deficits hidden at \"normal\")","0 versus 1","2 versus 3"],"correct":0,"explanation":"Yes — it measures force in kilograms or newtons, so smaller differences and change over time become visible.","href":"/learn/mmt-grading-0-to-5","linkTitle":"Manual Muscle Testing — The 0 to 5 Scale Without Guesswork"},{"id":"lq-mmt-lower-limb-gluteals-1","topic":"Skills · Measurement","question":"In the hip abduction test, the patient's leg drifts forward and rotates as it rises. Which muscle is substituting?","options":["Adductor longus","Tensor fasciae latae (and hip flexors) for a weak gluteus medius","Gluteus maximus"],"correct":1,"explanation":"Yes — TFL abducts with flexion and internal rotation, so a leg that drifts forward is the cheat. Keep the hip slightly extended and neutral.","href":"/learn/mmt-lower-limb-gluteals","linkTitle":"MMT of the Hip, Knee and Ankle — Gluteals, Quadriceps and the Calf"},{"id":"lq-mmt-lower-limb-gluteals-2","topic":"Skills · Measurement","question":"How do you grade calf strength reliably?","options":["Ask the patient to push their foot into the floor","Push on the sole with your hand","Count full single-leg heel raises (about 20–25 is normal; one raise is grade 3)"],"correct":2,"explanation":"Yes — functional testing for large muscles is more valid than hand resistance.","href":"/learn/mmt-lower-limb-gluteals","linkTitle":"MMT of the Hip, Knee and Ankle — Gluteals, Quadriceps and the Calf"},{"id":"lq-mmt-lower-limb-gluteals-3","topic":"Skills · Measurement","question":"Which position isolates the gluteus maximus rather than the hamstrings?","options":["Prone with the knee bent 90°","Supine with the hip flexed","Prone with the knee straight"],"correct":0,"explanation":"Yes — a bent knee slackens the hamstrings so the glute does the work.","href":"/learn/mmt-lower-limb-gluteals","linkTitle":"MMT of the Hip, Knee and Ankle — Gluteals, Quadriceps and the Calf"},{"id":"lq-mmt-upper-limb-substitutions-1","topic":"Skills · Measurement","question":"During shoulder abduction testing, a patient's shoulder rises toward the ear as the arm lifts. What is happening?","options":["The upper trapezius is substituting for a weak deltoid or supraspinatus","The patient is just stretching","The deltoid is very strong"],"correct":0,"explanation":"Yes — a shrug during shoulder flexion or abduction is the classic upper trapezius cheat. Ask the patient to relax the shoulder and stabilise the scapula.","href":"/learn/mmt-upper-limb-substitutions","linkTitle":"MMT of the Shoulder Girdle and Arm — Catching the Cheats"},{"id":"lq-mmt-upper-limb-substitutions-2","topic":"Skills · Measurement","question":"In the prone middle trapezius test, the patient rotates the trunk to lift the arm higher. What should you do?","options":["Accept the larger range and record 5/5","Stop the test and skip the muscle","Stabilise the trunk and ask the patient to lift only the arm; note the grade you can get without the trunk"],"correct":2,"explanation":"Yes — the grade is only valid for the arm movement without trunk rotation.","href":"/learn/mmt-upper-limb-substitutions","linkTitle":"MMT of the Shoulder Girdle and Arm — Catching the Cheats"},{"id":"lq-mmt-upper-limb-substitutions-3","topic":"Skills · Measurement","question":"A patient flexes the elbow but their wrist flexes first and the shoulder swings forward. What substitution is this?","options":["A nerve palsy","Wrist flexors and shoulder flexors substituting for a weak biceps/brachialis","Normal elbow flexion"],"correct":1,"explanation":"Yes — support the upper arm, keep the wrist neutral and retest.","href":"/learn/mmt-upper-limb-substitutions","linkTitle":"MMT of the Shoulder Girdle and Arm — Catching the Cheats"},{"id":"lq-motor-learning-neuroplasticity-1","topic":"Neurology","question":"A patient after stroke practises sit-to-stand 30 times from the same plinth and does it perfectly. At home, from a low sofa, they can't. What principle was missed?","options":["Variable practice for transfer — different heights, surfaces and contexts","Too much feedback was given","Not enough repetitions"],"correct":0,"explanation":"Yes — blocked practice from one surface built performance, not transferable learning.","href":"/learn/motor-learning-neuroplasticity","linkTitle":"Motor Learning & Neuroplasticity — How Patients Really Relearn Movement"},{"id":"lq-motor-learning-neuroplasticity-2","topic":"Neurology","question":"Which plan best applies the principles of neuroplasticity for a patient relearning reaching after stroke?","options":["10 passive range-of-motion movements, three times a week","Electrical stimulation alone","Hundreds of active reaches daily to real objects at varied heights, with home practice"],"correct":2,"explanation":"Yes — specific, repetitive, intense, varied and meaningful.","href":"/learn/motor-learning-neuroplasticity","linkTitle":"Motor Learning & Neuroplasticity — How Patients Really Relearn Movement"},{"id":"lq-motor-learning-neuroplasticity-3","topic":"Neurology","question":"Your patient is in the associative stage of learning to walk with a stick. Which feedback approach fits best?","options":["Correct every step out loud","Give no information at all","Let them walk a few lengths, then give brief summary feedback or ask how they think it went"],"correct":2,"explanation":"Yes — reduced, summary and learner-requested feedback builds self-correction.","href":"/learn/motor-learning-neuroplasticity","linkTitle":"Motor Learning & Neuroplasticity — How Patients Really Relearn Movement"},{"id":"lq-mulligan-mobilization-with-movement-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does PILL response mean?","options":["Pain-free, Instant result, Long-lasting. The three signs that an MWM is right.","A little extra gentle pressure at the end of movement, only if painless.","A held, comfortable joint glide that does not oscillate."],"correct":0,"explanation":"Exactly! PILL response — Pain-free, Instant result, Long-lasting. The three signs that an MWM is right.","href":"/manual-therapy/mulligan-mobilization-with-movement","linkTitle":"Mulligan Mobilization With Movement (MWM)"},{"id":"lq-mulligan-mobilization-with-movement-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use Mulligan Mobilization With Movement (MWM) (or to stop and reassess)?","options":["A clearly painful or restricted movement that is easy to repeat, for example painful gripping at the elbow or restricted ankle dorsiflexion.","No immediate pain-free improvement after a few careful tries.","Joints that can be glided safely in a direction that changes the movement at once."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/mulligan-mobilization-with-movement","linkTitle":"Mulligan Mobilization With Movement (MWM)"},{"id":"lq-mulligan-snags-nags-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does Apophyseal joint mean?","options":["Another name for the facet joint, the small paired joints at the back of each vertebra.","A version where the patient holds a towel or their fingers on the vertebra and applies the glide themselves.","A held glide with the patient moving through it."],"correct":0,"explanation":"Exactly! Apophyseal joint — Another name for the facet joint, the small paired joints at the back of each vertebra.","href":"/manual-therapy/mulligan-snags-nags","linkTitle":"Mulligan NAGs, SNAGs & Self-SNAGs"},{"id":"lq-mulligan-snags-nags-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use Mulligan NAGs, SNAGs & Self-SNAGs (or to stop and reassess)?","options":["Painful neck rotation or flexion where a segment is tender.","Headaches arising from the upper neck that are reproduced by neck movement.","Dizziness, visual disturbance, difficulty speaking or swallowing, or any neurological sign."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/mulligan-snags-nags","linkTitle":"Mulligan NAGs, SNAGs & Self-SNAGs"},{"id":"lq-muscle-contraction-types-1","topic":"Movement Science","question":"During the lowering phase of a push-up, the triceps and pectoralis major are working…","options":["Concentrically","Eccentrically","They are switched off; gravity does it"],"correct":1,"explanation":"Yes — they lengthen under load to control the descent.","href":"/learn/muscle-contraction-types","linkTitle":"Muscle Contraction — Concentric, Eccentric, Isometric & Length–Tension"},{"id":"lq-muscle-contraction-types-2","topic":"Movement Science","question":"Why is it hard to make a strong fist with your wrist fully flexed?","options":["The wrist extensors are too weak","The finger flexors are too short to make much force — active insufficiency","Nerves are compressed at the wrist"],"correct":1,"explanation":"Exactly — the length–tension curve in action. The two-joint finger flexors are shortened over both wrist and fingers.","href":"/learn/muscle-contraction-types","linkTitle":"Muscle Contraction — Concentric, Eccentric, Isometric & Length–Tension"},{"id":"lq-muscle-contraction-types-3","topic":"Movement Science","question":"A sprinter's hamstring is most often injured in late swing, as the knee extends rapidly. What is the hamstring doing then?","options":["Contracting eccentrically to brake the swinging leg","Completely relaxed","Contracting concentrically to bend the knee"],"correct":0,"explanation":"Yes — high-force eccentric braking at long length. That's why eccentric training like the Nordic curl helps prevention.","href":"/learn/muscle-contraction-types","linkTitle":"Muscle Contraction — Concentric, Eccentric, Isometric & Length–Tension"},{"id":"lq-muscle-energy-technique-mechanics-1","topic":"Manual Therapy · Soft Tissue","question":"What effort should the patient use for a standard PIR contraction?","options":["A maximal effort","No contraction, just a stretch","A light effort, about 20% of their maximum"],"correct":2,"explanation":"Yes — a light contraction relaxes the muscle; a hard one tires it and makes the muscle tense.","href":"/learn/muscle-energy-technique-mechanics","linkTitle":"Muscle Energy Technique — Using the Patient's Own Contraction"},{"id":"lq-muscle-energy-technique-mechanics-2","topic":"Manual Therapy · Soft Tissue","question":"A patient's hamstring stops at a point where they feel a mild stretch. What is the best next step in PIR?","options":["Pull the leg further into pain","Ask for a light contraction against your hand and hold for 5 to 10 seconds","End the treatment"],"correct":1,"explanation":"Yes — that is the contraction step; then relax and take up the new range.","href":"/learn/muscle-energy-technique-mechanics","linkTitle":"Muscle Energy Technique — Using the Patient's Own Contraction"},{"id":"lq-muscle-energy-technique-mechanics-3","topic":"Manual Therapy · Soft Tissue","question":"Which patient is a poor choice for MET today?","options":["A patient with a mildly tight hamstring after sport","A patient with a stiff hip after a long flight","A patient with a suspected acute muscle tear and severe pain"],"correct":2,"explanation":"Right — severe pain and a suspected tear call for protection, not a contraction against resistance.","href":"/learn/muscle-energy-technique-mechanics","linkTitle":"Muscle Energy Technique — Using the Patient's Own Contraction"},{"id":"lq-muscle-energy-technique-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Barrier mean?","options":["The point where movement first meets resistance.","A contraction without joint movement.","The reduced tension often felt after a gentle hold."],"correct":0,"explanation":"Exactly! Barrier — The point where movement first meets resistance.","href":"/manual-therapy/muscle-energy-technique","linkTitle":"Muscle Energy Technique (MET)"},{"id":"lq-muscle-energy-technique-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Muscle Energy Technique (MET) (or to stop and reassess)?","options":["Joint stiffness where a muscle contributes, such as a restricted neck rotation.","Fracture, acute tear, severe osteoporosis or instability.","Muscle tightness limiting range, for example hamstrings or hip muscles."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/muscle-energy-technique","linkTitle":"Muscle Energy Technique (MET)"},{"id":"lq-muscle-length-testing-1","topic":"Skills · Measurement","question":"In the modified Thomas test the thigh lifts off the plinth but the knee angle is normal. Which muscle is short?","options":["Iliopsoas (a one-joint hip flexor)","Hamstrings","Rectus femoris"],"correct":0,"explanation":"Yes — the thigh stays up because the hip cannot reach extension; a normal knee angle excludes rectus femoris.","href":"/learn/muscle-length-testing","linkTitle":"Muscle Length Testing — Thomas, Ely, Ober, Straight-Leg Raise and the Calf"},{"id":"lq-muscle-length-testing-2","topic":"Skills · Measurement","question":"Which finding means the gastrocnemius (not the soleus) is short?","options":["Dorsiflexion is equally limited with the knee straight and bent","Dorsiflexion is limited with the knee straight but improves a lot with the knee bent","Plantarflexion is limited"],"correct":1,"explanation":"Yes — bending the knee slackens the gastrocnemius; whatever remains limited belongs to the soleus or the ankle joint.","href":"/learn/muscle-length-testing","linkTitle":"Muscle Length Testing — Thomas, Ely, Ober, Straight-Leg Raise and the Calf"},{"id":"lq-muscle-length-testing-3","topic":"Skills · Measurement","question":"Which end-feel suggests a short muscle rather than a joint block?","options":["Firm and slightly elastic, with the stretch felt in the muscle","Empty — pain stops you before resistance","Hard and abrupt"],"correct":0,"explanation":"Yes — a hard, abrupt end-feel suggests bone or joint, and empty means pain stops you first.","href":"/learn/muscle-length-testing","linkTitle":"Muscle Length Testing — Thomas, Ely, Ober, Straight-Leg Raise and the Calf"},{"id":"lq-myofascial-decompression-dry-cupping-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Negative pressure mean?","options":["Cups held in place.","Suction that lifts the tissue.","Cups glided across the skin."],"correct":1,"explanation":"Exactly! Negative pressure — Suction that lifts the tissue.","href":"/manual-therapy/myofascial-decompression-dry-cupping","linkTitle":"Myofascial Decompression / Dry Cupping"},{"id":"lq-myofascial-decompression-dry-cupping-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Myofascial Decompression / Dry Cupping (or to stop and reassess)?","options":["As an adjunct before movement exercises.","Skin infection, open wounds, sunburn or fragile skin.","Muscle tightness or soreness where a patient prefers or tolerates cupping."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/myofascial-decompression-dry-cupping","linkTitle":"Myofascial Decompression / Dry Cupping"},{"id":"lq-myofascial-release-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Fascia mean?","options":["Connective tissue wrapping muscles, bones and organs.","Gently loading tissue into the barrier.","The point where tissue first resists."],"correct":0,"explanation":"Exactly! Fascia — Connective tissue wrapping muscles, bones and organs.","href":"/manual-therapy/myofascial-release","linkTitle":"Myofascial Release (Direct & Indirect)"},{"id":"lq-myofascial-release-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Myofascial Release (Direct & Indirect) (or to stop and reassess)?","options":["Open wounds, infection, acute inflammation, or fresh surgery.","Post-surgical or postural tightness once safe to load.","Tight, restricted areas where gentle sustained contact is acceptable."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/myofascial-release","linkTitle":"Myofascial Release (Direct & Indirect)"},{"id":"lq-myotome-screening-root-levels-1","topic":"Skills · Neuro Exam","question":"A patient cannot hold the shoulder out against resistance, but the elbow bends and wrist extends normally. Which root is the first suspect?","options":["C5","C7","C8"],"correct":0,"explanation":"Yes — shoulder abduction is the C5 key muscle (deltoid, supraspinatus). Elbow flexion and wrist extension are C6 and are spared.","href":"/learn/myotome-screening-root-levels","linkTitle":"Myotome Screening — Which Root Is Weak?"},{"id":"lq-myotome-screening-root-levels-2","topic":"Skills · Neuro Exam","question":"A man with right leg pain has weak big-toe extension and numbness over the top of the foot. Which disc is the most likely culprit?","options":["L5–S1 disc","L4–L5 posterolateral disc (compressing L5)","C6–C7 disc"],"correct":1,"explanation":"Yes — big-toe extension and the dorsum of the foot are both L5, and an L4–L5 disc compresses the traversing L5 root.","href":"/learn/myotome-screening-root-levels","linkTitle":"Myotome Screening — Which Root Is Weak?"},{"id":"lq-myotome-screening-root-levels-3","topic":"Skills · Neuro Exam","question":"Foot drop, weak hip abduction and weak inversion. Where is the lesion?","options":["L5 root","Common fibular nerve at the fibular head","Sciatic nerve in the thigh"],"correct":0,"explanation":"Yes — three different nerves are affected, but they share the L5 root.","href":"/learn/myotome-screening-root-levels","linkTitle":"Myotome Screening — Which Root Is Weak?"},{"id":"lq-neural-mobilisation-neurodynamics-1","topic":"Manual Therapy","question":"During a slump test the patient's calf pain eases when you release the neck flexion. What does this suggest?","options":["It is a hamstring muscle strain","The test is negative and can be ignored","The nerve is involved, because a distant movement changed the symptoms"],"correct":2,"explanation":"Yes — structural differentiation shows the symptom comes from the nerve system, not just the local muscle.","href":"/learn/neural-mobilisation-neurodynamics","linkTitle":"Neural Mobilisation — Testing and Treating the Nerve as a Moving Structure"},{"id":"lq-neural-mobilisation-neurodynamics-2","topic":"Manual Therapy","question":"Which finding is the best sign that you progressed too far?","options":["The patient feels the movement is easy","Symptoms linger or are worse an hour after the treatment","A mild familiar tingle that goes in a minute"],"correct":1,"explanation":"Right — lingering or worse symptoms mean the dose was too high; reduce the range or the tension.","href":"/learn/neural-mobilisation-neurodynamics","linkTitle":"Neural Mobilisation — Testing and Treating the Nerve as a Moving Structure"},{"id":"lq-neural-mobilisation-neurodynamics-3","topic":"Manual Therapy","question":"What makes a neurodynamic test positive?","options":["The patient feels a stretch behind the thigh","It reproduces the patient's own symptoms and changes with structural differentiation","The leg cannot be raised past 30°"],"correct":1,"explanation":"Yes — both parts are needed, otherwise a stretch of the hamstring could be mistaken for a nerve sign.","href":"/learn/neural-mobilisation-neurodynamics","linkTitle":"Neural Mobilisation — Testing and Treating the Nerve as a Moving Structure"},{"id":"lq-neurodynamic-mobilization-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does Neural tension test mean?","options":["A movement that slides the nerve without increasing overall tension.","A sequence of limb positions that stresses a nerve, for example the upper limb tension test for the median nerve.","A movement that raises tension along the nerve."],"correct":1,"explanation":"Exactly! Neural tension test — A sequence of limb positions that stresses a nerve, for example the upper limb tension test for the median nerve.","href":"/manual-therapy/neurodynamic-mobilization","linkTitle":"Neurodynamic Mobilization"},{"id":"lq-neurodynamic-mobilization-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use Neurodynamic Mobilization (or to stop and reassess)?","options":["Nerve irritation after injury or entrapment where movement is guarded.","Worsening weakness, spinal cord signs or cauda equina symptoms.","Arm or leg symptoms (tingling, aching, pulling) reproduced by neural tension positions with a clear pattern."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/neurodynamic-mobilization","linkTitle":"Neurodynamic Mobilization"},{"id":"lq-open-vs-closed-chain-1","topic":"Movement Science","question":"A patient's quadriceps is much weaker than the other muscles of the leg. Which exercise best ISOLATES the quadriceps?","options":["Walking lunge","Seated knee extension","Squat"],"correct":1,"explanation":"Right — open chain and single-joint, so the quadriceps can't hide behind the hip and ankle muscles.","href":"/learn/open-vs-closed-chain","linkTitle":"Open vs Closed Kinetic Chain — The Foot Decides"},{"id":"lq-open-vs-closed-chain-2","topic":"Movement Science","question":"Which exercise best combines several lower-limb joints with the foot fixed — closest to rising from a chair?","options":["Hamstring curl machine","Seated knee extension","Sit-to-stand"],"correct":2,"explanation":"Yes — closed chain, multi-joint and directly task-specific.","href":"/learn/open-vs-closed-chain","linkTitle":"Open vs Closed Kinetic Chain — The Foot Decides"},{"id":"lq-open-vs-closed-chain-3","topic":"Movement Science","question":"A patient lies supine and lifts a straight leg off the bed. Which type of exercise is this?","options":["Closed kinetic chain","Open kinetic chain"],"correct":1,"explanation":"Right — the foot is free in the air.","href":"/learn/open-vs-closed-chain","linkTitle":"Open vs Closed Kinetic Chain — The Foot Decides"},{"id":"lq-orthostatic-hypotension-screen-1","topic":"Skills · Vitals & Monitoring","question":"Which result is a positive orthostatic test?","options":["Pulse rises from 70 to 90","Systolic falls from 130 to 122 mmHg","Systolic falls from 130 to 108 mmHg within 3 minutes of standing"],"correct":2,"explanation":"Yes — a fall of 20 mmHg or more systolic (or 10 diastolic) is positive.","href":"/learn/orthostatic-hypotension-screen","linkTitle":"Orthostatic Hypotension — Screening Before You Stand a Patient Up"},{"id":"lq-orthostatic-hypotension-screen-2","topic":"Skills · Vitals & Monitoring","question":"A patient's pulse barely rises (65 to 68) while systolic pressure falls by 30 mmHg on standing. What does this suggest?","options":["A normal response","A neurogenic cause (autonomic failure), not simple dehydration","Dehydration only"],"correct":1,"explanation":"Yes — in volume depletion the heart rate rises to compensate; a flat heart-rate response suggests the reflex arc itself is impaired.","href":"/learn/orthostatic-hypotension-screen","linkTitle":"Orthostatic Hypotension — Screening Before You Stand a Patient Up"},{"id":"lq-orthostatic-hypotension-screen-3","topic":"Skills · Vitals & Monitoring","question":"Which instruction helps prevent a faint when standing up?","options":["Avoid fluids to reduce dizziness","Stand quickly to get it over with","Sit at the edge of the bed first, pump the ankles and stand up slowly with support"],"correct":2,"explanation":"Yes — staged position changes give the reflex time to catch up.","href":"/learn/orthostatic-hypotension-screen","linkTitle":"Orthostatic Hypotension — Screening Before You Stand a Patient Up"},{"id":"lq-osteopathic-articulatory-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Articulation mean?","options":["How big the movement is.","Repeated passive movement of a joint.","The point where resistance begins."],"correct":1,"explanation":"Exactly! Articulation — Repeated passive movement of a joint.","href":"/manual-therapy/osteopathic-articulatory","linkTitle":"Osteopathic Articulatory Techniques"},{"id":"lq-osteopathic-articulatory-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Osteopathic Articulatory Techniques (or to stop and reassess)?","options":["Stiff joints, such as the mid-back, where gentle repeated movement is suitable.","Fractures, osteoporosis concerns, infection or instability.","People who prefer a non-thrust method."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/osteopathic-articulatory","linkTitle":"Osteopathic Articulatory Techniques"},{"id":"lq-osteopathic-articulatory-4","topic":"Manual Therapy · World Approaches","question":"A thoracic movement is easier after gentle guidance. Best next step?","options":["Tell the patient the joint is now permanently aligned.","Integrate active motion and exercise, and retest a relevant task.","Repeat passive treatment indefinitely."],"correct":1,"explanation":"A short-term response can create an opportunity for active rehabilitation; it is not proof of permanent structural change.","href":"/manual-therapy/osteopathic-articulatory","linkTitle":"Osteopathic Articulatory Techniques"},{"id":"lq-osteopathic-lymphatic-pump-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Lymphatic pump mean?","options":["Rhythmic movement at the feet.","Rhythmic pressure on the chest wall.","Rhythmic compression intended to move lymph."],"correct":2,"explanation":"Exactly! Lymphatic pump — Rhythmic compression intended to move lymph.","href":"/manual-therapy/osteopathic-lymphatic-pump","linkTitle":"Osteopathic Lymphatic Pump Methods"},{"id":"lq-osteopathic-lymphatic-pump-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Osteopathic Lymphatic Pump Methods (or to stop and reassess)?","options":["Gentle chest-wall mobility work when appropriate.","Trained practitioners offering it as an adjunct, with medical approval where there is infection.","Rib fractures, severe osteoporosis, or recent chest or abdominal surgery."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/osteopathic-lymphatic-pump","linkTitle":"Osteopathic Lymphatic Pump Methods"},{"id":"lq-osteopathic-lymphatic-pump-4","topic":"Manual Therapy · World Approaches","question":"A hot, swollen calf appears after prolonged immobilization. What is the priority?","options":["Perform an intense pump session.","Assume normal post-exercise soreness.","Assess urgently for DVT and do not massage the limb."],"correct":2,"explanation":"DVT is a potentially serious condition; manual pumping is inappropriate until a safe diagnosis and care plan are established.","href":"/manual-therapy/osteopathic-lymphatic-pump","linkTitle":"Osteopathic Lymphatic Pump Methods"},{"id":"lq-osteoporosis-exercise-bone-health-1","topic":"Geriatrics","question":"Which movement should be avoided after a vertebral fracture?","options":["Standing balance practice","Loaded forward bending, such as touching the toes while lifting or doing sit-ups","Walking regularly"],"correct":1,"explanation":"Yes — forward bending under load compresses the front of the vertebrae.","href":"/learn/osteoporosis-exercise-bone-health","linkTitle":"Osteoporosis — Exercising Safely to Protect Bones"},{"id":"lq-osteoporosis-exercise-bone-health-2","topic":"Geriatrics","question":"What should happen before exercise for a person with sudden new mid-back pain after a small strain?","options":["Complete bed rest for months","Medical review for a possible vertebral fracture","Heavy back-extension exercise straight away"],"correct":1,"explanation":"Yes — a vertebral fracture must be confirmed and managed before loading the spine.","href":"/learn/osteoporosis-exercise-bone-health","linkTitle":"Osteoporosis — Exercising Safely to Protect Bones"},{"id":"lq-osteoporosis-exercise-bone-health-3","topic":"Geriatrics","question":"Which exercise helps bone and also lowers the risk of falling?","options":["Sit-ups and toe touches with a rounded back","Complete rest","Brisk walking, sit-to-stand and balance practice done regularly"],"correct":2,"explanation":"Yes — load builds bone and balance with leg strength prevents falls.","href":"/learn/osteoporosis-exercise-bone-health","linkTitle":"Osteoporosis — Exercising Safely to Protect Bones"},{"id":"lq-outcome-measures-minimal-important-change-1","topic":"Research & Evidence","question":"Which statement describes the minimal important change?","options":["Any change at all","The change that is statistically significant","The smallest change that a patient would consider worthwhile"],"correct":2,"explanation":"Yes — it is based on the patient's view of benefit.","href":"/learn/outcome-measures-minimal-important-change","linkTitle":"Outcome Measures — Is the Change Real and Does It Matter?"},{"id":"lq-outcome-measures-minimal-important-change-2","topic":"Research & Evidence","question":"A patient's numeric pain score falls from 7 to 6. How should you describe this?","options":["Proof the treatment has failed","A small change that is below the usual important change; keep monitoring and discuss function","A clear success"],"correct":1,"explanation":"Yes — about 2 points or 30 percent is usually needed.","href":"/learn/outcome-measures-minimal-important-change","linkTitle":"Outcome Measures — Is the Change Real and Does It Matter?"},{"id":"lq-outcome-measures-minimal-important-change-3","topic":"Research & Evidence","question":"Which tool property tells you that it gives the same result when nothing has changed?","options":["Reliability","Responsiveness","Validity"],"correct":0,"explanation":"Yes — reliability is about repeatability.","href":"/learn/outcome-measures-minimal-important-change","linkTitle":"Outcome Measures — Is the Change Real and Does It Matter?"},{"id":"lq-oximetry-temperature-capillary-refill-1","topic":"Skills · Vitals & Monitoring","question":"A patient's SpO₂ reads 82%, but the waveform is jagged, the hand is cold and the patient is shivering. What should you do first?","options":["Ignore the reading since it is always wrong","Warm the hand, keep it still, try another finger and check the patient clinically before acting on the number","Start oxygen immediately without checking"],"correct":1,"explanation":"Yes — poor perfusion, cold and movement give false lows; look at the patient and repeat.","href":"/learn/oximetry-temperature-capillary-refill","linkTitle":"SpO₂, Temperature and Capillary Refill — Reading the Small Numbers Safely"},{"id":"lq-oximetry-temperature-capillary-refill-2","topic":"Skills · Vitals & Monitoring","question":"Which finding means \"stop exercise now\"?","options":["SpO₂ falling below about 88–90 % with breathlessness or dizziness","Capillary refill of 1.5 seconds","Temperature of 36.8 °C"],"correct":0,"explanation":"Yes — symptoms plus a falling saturation mean the patient is not tolerating the load.","href":"/learn/oximetry-temperature-capillary-refill","linkTitle":"SpO₂, Temperature and Capillary Refill — Reading the Small Numbers Safely"},{"id":"lq-oximetry-temperature-capillary-refill-3","topic":"Skills · Vitals & Monitoring","question":"A patient with COPD has a target SpO₂ of 88–92%. Their reading is 90%. What does this mean?","options":["It means the oximeter is broken","It is dangerously low in everyone","It is within their prescribed target, so no automatic alarm, but watch symptoms"],"correct":2,"explanation":"Yes — targets are individualised; high oxygen can be harmful in some COPD patients.","href":"/learn/oximetry-temperature-capillary-refill","linkTitle":"SpO₂, Temperature and Capillary Refill — Reading the Small Numbers Safely"},{"id":"lq-pain-science-basics-2","topic":"Pain Science","question":"Two patients have the same lumbar MRI findings. One has severe pain, the other has none. What's the best explanation?","options":["Pain depends on many factors, not just tissue findings","The MRI must be wrong","One of them is not telling the truth"],"correct":0,"explanation":"Exactly. And disc bulges and degeneration are very common in people with no pain at all — imaging is only one piece of the picture.","href":"/learn/pain-science-basics","linkTitle":"Pain Science Basics — Why Hurt ≠ Harm"},{"id":"lq-pain-science-basics-3","topic":"Pain Science","question":"Which phrase is BEST to say to a patient with persistent low back pain?","options":["\"There's nothing wrong with you.\"","\"Hurt doesn't always mean harm — we'll build up your activity step by step.\"","\"Your disc is degenerated, so avoid bending.\""],"correct":1,"explanation":"Perfect. Validating, reassuring and action-focused. That's how a great clinician talks.","href":"/learn/pain-science-basics","linkTitle":"Pain Science Basics — Why Hurt ≠ Harm"},{"id":"lq-paivm-ppivm-spinal-assessment-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does PA (posteroanterior) glide mean?","options":["Stiffer than expected / moving more than expected.","Central pushes on the spinous process in the midline. Unilateral pushes on one side near the facet.","Pushing a vertebra from back to front."],"correct":2,"explanation":"Exactly! PA (posteroanterior) glide — Pushing a vertebra from back to front.","href":"/manual-therapy/paivm-ppivm-spinal-assessment","linkTitle":"PAIVM & PPIVM Spinal Assessment / Mobilization"},{"id":"lq-paivm-ppivm-spinal-assessment-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use PAIVM & PPIVM Spinal Assessment / Mobilization (or to stop and reassess)?","options":["Suspected fracture, instability or serious pathology (use medical assessment first).","Before choosing mobilization level and direction.","Back or neck pain where you want to find the most relevant segment."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/paivm-ppivm-spinal-assessment","linkTitle":"PAIVM & PPIVM Spinal Assessment / Mobilization"},{"id":"lq-palpation-lower-limb-ottawa-rules-1","topic":"Skills · Posture & Palpation","question":"The dorsalis pedis pulse is absent in an otherwise healthy young runner. What should you do before concluding the foot has no pulse?","options":["Refer urgently for acute limb ischaemia","Assume it is normal and move on","Check the posterior tibial pulse and the foot's colour, temperature and capillary refill"],"correct":2,"explanation":"Yes — the dorsalis pedis is congenitally absent in about 1 in 10 people. Look at the whole picture.","href":"/learn/palpation-lower-limb-ottawa-rules","linkTitle":"Palpation of the Hip, Knee and Ankle — Pulses, Landmarks and the Ottawa Rules"},{"id":"lq-palpation-lower-limb-ottawa-rules-2","topic":"Skills · Posture & Palpation","question":"A patient with an ankle sprain has no tenderness over the malleoli or the 5th metatarsal base and walks four steps. What do the Ottawa rules say?","options":["Refer for MRI","An X-ray is not needed (fracture is very unlikely)","Always X-ray every sprained ankle"],"correct":1,"explanation":"Yes — the rules are highly sensitive, so a negative result safely avoids unnecessary imaging.","href":"/learn/palpation-lower-limb-ottawa-rules","linkTitle":"Palpation of the Hip, Knee and Ankle — Pulses, Landmarks and the Ottawa Rules"},{"id":"lq-palpation-lower-limb-ottawa-rules-3","topic":"Skills · Posture & Palpation","question":"Which landmark is checked for the foot series in the Ottawa rules?","options":["The calcaneal tuberosity","The head of the 1st metatarsal","The base of the 5th metatarsal and the navicular"],"correct":2,"explanation":"Yes — bone tenderness at these two sites calls for a foot X-ray.","href":"/learn/palpation-lower-limb-ottawa-rules","linkTitle":"Palpation of the Hip, Knee and Ankle — Pulses, Landmarks and the Ottawa Rules"},{"id":"lq-palpation-spinal-levels-1","topic":"Skills · Posture & Palpation","question":"How do you confirm that the prominent bump is C7 and not T1?","options":["Extend the neck: C7 stays still while C6 moves forward and disappears","It is always the biggest bump on the spine","It is level with the nipples"],"correct":0,"explanation":"Yes — C6 glides forward with extension, T1 does not move, so the bump that stays is C7 (or T1 in a few people); combine with counting upwards.","href":"/learn/palpation-spinal-levels","linkTitle":"Palpation of Spinal Levels — C7, T3, T7, L4 and S2"},{"id":"lq-palpation-spinal-levels-2","topic":"Skills · Posture & Palpation","question":"Your count from C7 and your count from the iliac crests disagree by one level. What is the best action?","options":["Choose the count you prefer and carry on","Repeat with other landmarks, record the level as approximate and avoid decisions that need an exact level","Always trust the iliac crests"],"correct":1,"explanation":"Yes — honest uncertainty is safer than false precision.","href":"/learn/palpation-spinal-levels","linkTitle":"Palpation of Spinal Levels — C7, T3, T7, L4 and S2"},{"id":"lq-palpation-spinal-levels-3","topic":"Skills · Posture & Palpation","question":"Which landmark marks the L4 level?","options":["The PSIS","The line joining the highest points of the iliac crests (Tuffier's line)","The inferior angle of the scapula"],"correct":1,"explanation":"Yes — it passes through the L4 spinous process or the L4–L5 space.","href":"/learn/palpation-spinal-levels","linkTitle":"Palpation of Spinal Levels — C7, T3, T7, L4 and S2"},{"id":"lq-palpation-upper-body-landmarks-1","topic":"Skills · Posture & Palpation","question":"Why is the sternal angle clinically useful?","options":["It marks the 2nd rib, so you can count the ribs and find the T4–T5 level","It marks the xiphoid process","It marks the first rib"],"correct":0,"explanation":"Yes — it is the best starting point for counting ribs and for auscultation landmarks.","href":"/learn/palpation-upper-body-landmarks","linkTitle":"Palpation of the Chest, Shoulder and Elbow — From the Jugular Notch to the Epicondyles"},{"id":"lq-palpation-upper-body-landmarks-2","topic":"Skills · Posture & Palpation","question":"A patient falls on the shoulder and is tender and has a step at the top of the shoulder over the outer clavicle. Which joint is most likely injured?","options":["The glenohumeral joint","The acromioclavicular (AC) joint","The sternoclavicular joint"],"correct":1,"explanation":"Yes — a step and tenderness at the AC joint after a fall suggests an AC sprain or separation.","href":"/learn/palpation-upper-body-landmarks","linkTitle":"Palpation of the Chest, Shoulder and Elbow — From the Jugular Notch to the Epicondyles"},{"id":"lq-palpation-upper-body-landmarks-3","topic":"Skills · Posture & Palpation","question":"Which tendon attaches at the lateral epicondyle?","options":["The biceps tendon","The common flexor tendon","The common extensor tendon"],"correct":2,"explanation":"Yes — hence \"tennis elbow\" is lateral epicondylalgia.","href":"/learn/palpation-upper-body-landmarks","linkTitle":"Palpation of the Chest, Shoulder and Elbow — From the Jugular Notch to the Epicondyles"},{"id":"lq-paris-approach-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Hypomobile mean?","options":["A joint moving more than expected; usually needs stability, not stretching.","Small passive movements of a joint surface the patient cannot do actively.","A joint moving less than expected."],"correct":2,"explanation":"Exactly! Hypomobile — A joint moving less than expected.","href":"/manual-therapy/paris-approach","linkTitle":"Paris Approach to Orthopedic Manual Therapy"},{"id":"lq-paris-approach-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Paris Approach to Orthopedic Manual Therapy (or to stop and reassess)?","options":["Joint or spine problems where you need a clear reason for choosing manual therapy.","Teaching and learning systematic examination.","When red flags need medical review first."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/paris-approach","linkTitle":"Paris Approach to Orthopedic Manual Therapy"},{"id":"lq-paris-approach-4","topic":"Manual Therapy · World Approaches","question":"A patient reports a restricted overhead reach but the chosen glide makes no meaningful difference. What next?","options":["Label the patient non-compliant.","Increase force until the textbook glide works.","Reassess the hypothesis and choose a better-supported plan."],"correct":2,"explanation":"A meaningful comparable-sign response and safety guide treatment. Do not defend a technique against the patient's findings.","href":"/manual-therapy/paris-approach","linkTitle":"Paris Approach to Orthopedic Manual Therapy"},{"id":"lq-pelvic-floor-pregnancy-postnatal-1","topic":"Women's Health","question":"Which instruction gives the best chance of a correct pelvic floor contraction?","options":["Practise stopping the urine mid-stream every time","Squeeze and lift as if holding back wind, while breathing normally","Hold the breath and squeeze the buttocks hard"],"correct":1,"explanation":"Yes — a lift without breath holding or buttock squeezing targets the right muscles.","href":"/learn/pelvic-floor-pregnancy-postnatal","linkTitle":"The Pelvic Floor — Leaks, Pregnancy and Life After Childbirth"},{"id":"lq-pelvic-floor-pregnancy-postnatal-2","topic":"Women's Health","question":"Which finding means a woman should see a doctor before training?","options":["Mild tiredness after training","Leaking only when she coughs","A bulge or heaviness in the vagina with heavy bleeding or fever"],"correct":2,"explanation":"Yes — these signs need medical assessment.","href":"/learn/pelvic-floor-pregnancy-postnatal","linkTitle":"The Pelvic Floor — Leaks, Pregnancy and Life After Childbirth"},{"id":"lq-pelvic-floor-pregnancy-postnatal-3","topic":"Women's Health","question":"When can a woman usually begin returning to running after birth?","options":["Gradually, once she has no leaking, heaviness or pain, often after about three months","As soon as bleeding stops, with no checks","Never again after a vaginal birth"],"correct":0,"explanation":"Yes — readiness, not a fixed date, decides; build up with strength and walking first.","href":"/learn/pelvic-floor-pregnancy-postnatal","linkTitle":"The Pelvic Floor — Leaks, Pregnancy and Life After Childbirth"},{"id":"lq-pelvic-girdle-pain-pregnancy-1","topic":"Women's Health","question":"Pain at the back of the pelvis, worse turning in bed and climbing stairs, with a positive thigh thrust test. What does this suggest?","options":["A disc prolapse with nerve compression","Pelvic girdle pain","A normal change that needs no help"],"correct":1,"explanation":"Yes — this pattern with a positive provocation test supports a pelvic joint cause.","href":"/learn/pelvic-girdle-pain-pregnancy","linkTitle":"Back and Pelvic Pain in Pregnancy — Examine, Reassure and Support"},{"id":"lq-pelvic-girdle-pain-pregnancy-2","topic":"Women's Health","question":"Which symptom in a pregnant woman with back pain needs urgent medical review?","options":["Severe headache with swollen hands and face or blurred vision","Pain after long standing","Pain when turning in bed"],"correct":0,"explanation":"Yes — these can be signs of pre-eclampsia and need urgent care.","href":"/learn/pelvic-girdle-pain-pregnancy","linkTitle":"Back and Pelvic Pain in Pregnancy — Examine, Reassure and Support"},{"id":"lq-pelvic-girdle-pain-pregnancy-3","topic":"Women's Health","question":"Which advice suits pelvic girdle pain?","options":["Complete bed rest until the baby is born","Daily deep squats to strengthen the pelvis","Keep walking in short, comfortable spells and avoid wide leg positions and single-leg standing"],"correct":2,"explanation":"Yes — gentle movement with even load keeps the joints calm.","href":"/learn/pelvic-girdle-pain-pregnancy","linkTitle":"Back and Pelvic Pain in Pregnancy — Examine, Reassure and Support"},{"id":"lq-pnf-manual-techniques-1","topic":"Manual Therapy · Joint","question":"Vocabulary first — clinicians use this word a lot. What does D1 / D2 patterns mean?","options":["Similar, using an isometric hold (no movement) of the tight muscle.","Diagonal movement patterns of the arm or leg that combine flexion or extension with rotation.","Stretch to the limit, patient contracts the tight muscle, relaxes, then you move to a new range."],"correct":1,"explanation":"Exactly! D1 / D2 patterns — Diagonal movement patterns of the arm or leg that combine flexion or extension with rotation.","href":"/manual-therapy/pnf-manual-techniques","linkTitle":"PNF Manual Techniques"},{"id":"lq-pnf-manual-techniques-2","topic":"Manual Therapy · Joint","question":"Safety check: which of these is a reason NOT to use PNF Manual Techniques (or to stop and reassess)?","options":["Muscle tightness limiting range (hamstrings, calves, shoulder muscles).","Weakness or poor control after injury or surgery.","Uncontrolled high blood pressure or heart conditions (avoid strong breath-holding)."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/pnf-manual-techniques","linkTitle":"PNF Manual Techniques"},{"id":"lq-posture-plumb-line-analysis-1","topic":"Skills · Posture & Palpation","question":"In a side view, the ear sits in front of the plumb line that passes through the shoulder. What do you call this, and which muscles are overloaded?","options":["Forward head posture; the posterior neck extensors and upper trapezius work harder","Sway-back posture; the abdominals work harder","Normal alignment; no muscles are loaded"],"correct":0,"explanation":"Yes — the head acts as a heavy weight in front of the spine, so the neck extensors must hold it up (and the deep neck flexors lengthen and weaken).","href":"/learn/posture-plumb-line-analysis","linkTitle":"Posture Analysis with a Plumb Line — Front, Back and Side"},{"id":"lq-posture-plumb-line-analysis-2","topic":"Skills · Posture & Palpation","question":"Which approach gives the most reliable posture information?","options":["A quick glance and a verbal description","Asking the patient whether their posture looks bad","Objective measures (photographs with angles, flexicurve, scoliometer, occiput-to-wall) taken the same way each time"],"correct":2,"explanation":"Yes — standardised, repeatable numbers can be compared between visits and between therapists.","href":"/learn/posture-plumb-line-analysis","linkTitle":"Posture Analysis with a Plumb Line — Front, Back and Side"},{"id":"lq-posture-plumb-line-analysis-3","topic":"Skills · Posture & Palpation","question":"A patient stands with one shoulder lower; it levels when she lies down. What is this?","options":["A structural deviation","A normal variation that cannot be measured","A functional (postural) deviation"],"correct":2,"explanation":"Yes — it corrects when gravity or the habitual position is removed.","href":"/learn/posture-plumb-line-analysis","linkTitle":"Posture Analysis with a Plumb Line — Front, Back and Side"},{"id":"lq-primitive-reflexes-postural-reactions-1","topic":"Paediatrics","question":"A 9-month-old still shows a strong, symmetrical Moro reflex whenever his head drops. What is the best interpretation?","options":["It is a good sign of strength","It has persisted beyond its usual window (about 4 to 6 months): look at tone, other reflexes and development, and refer for review","It is normal; Moro lasts for life"],"correct":1,"explanation":"Yes — a strong Moro after about 6 months suggests delayed inhibition and should be reviewed alongside the rest of the examination, not judged alone.","href":"/learn/primitive-reflexes-postural-reactions","linkTitle":"Primitive Reflexes and Postural Reactions: The Hidden Timeline of Infant Movement"},{"id":"lq-primitive-reflexes-postural-reactions-2","topic":"Paediatrics","question":"An 11-month-old can sit only when propped, and does not throw out his arms sideways or backwards when tipped. Which interpretation fits best?","options":["The Moro reflex has simply not faded yet","Normal: parachute reactions are not expected before 12 months","Parachute reactions are delayed, so sitting is unsafe and the child needs review of tone and posture"],"correct":2,"explanation":"Yes — sideways and backward parachutes should be present by about 9 months. Their absence puts the child at risk of falling over without protecting himself.","href":"/learn/primitive-reflexes-postural-reactions","linkTitle":"Primitive Reflexes and Postural Reactions: The Hidden Timeline of Infant Movement"},{"id":"lq-primitive-reflexes-postural-reactions-3","topic":"Paediatrics","question":"Which finding is the most concerning in a 2-month-old?","options":["A present, symmetrical rooting reflex","An asymmetrical or absent Moro reflex and a floppy arm on one side","A strong palmar grasp"],"correct":1,"explanation":"Yes — it can point to a fracture of the collarbone, a brachial plexus injury or hemiparesis, and needs prompt review.","href":"/learn/primitive-reflexes-postural-reactions","linkTitle":"Primitive Reflexes and Postural Reactions: The Hidden Timeline of Infant Movement"},{"id":"lq-pulse-blood-pressure-respiration-1","topic":"Skills · Vitals & Monitoring","question":"Why should you not use your thumb to take a pulse?","options":["The thumb presses too lightly","The thumb is too sensitive","The thumb has its own pulse, which can be mistaken for the patient's"],"correct":2,"explanation":"Yes — use the pads of the index and middle fingers.","href":"/learn/pulse-blood-pressure-respiration","linkTitle":"Pulse, Blood Pressure and Respiratory Rate — Getting Them Right Every Time"},{"id":"lq-pulse-blood-pressure-respiration-2","topic":"Skills · Vitals & Monitoring","question":"A patient's blood pressure is 152/94 immediately after climbing the stairs to your clinic. What should you do?","options":["Diagnose hypertension","Ignore the reading","Let them rest seated for 5 minutes and repeat the measurement before judging"],"correct":2,"explanation":"Yes — exercise raises blood pressure temporarily; a fair reading needs a rested patient.","href":"/learn/pulse-blood-pressure-respiration","linkTitle":"Pulse, Blood Pressure and Respiratory Rate — Getting Them Right Every Time"},{"id":"lq-pulse-blood-pressure-respiration-3","topic":"Skills · Vitals & Monitoring","question":"Which pulse finding needs a full 60-second count?","options":["A slow regular rhythm","A strong pulse","An irregular rhythm"],"correct":2,"explanation":"Yes — an irregular rhythm (for example atrial fibrillation) makes a 30-second count unreliable.","href":"/learn/pulse-blood-pressure-respiration","linkTitle":"Pulse, Blood Pressure and Respiratory Rate — Getting Them Right Every Time"},{"id":"lq-radiculopathy-myelopathy-neuropathy-1","topic":"Skills · Neuro Exam","question":"A 60-year-old has clumsy hands, difficulty with buttons, a stiff walk, brisk knee jerks and a positive Hoffmann sign. Where is the lesion?","options":["Peripheral neuropathy","The cervical spinal cord (degenerative cervical myelopathy)","A C6 nerve root"],"correct":1,"explanation":"Yes — clumsy hands, gait change and UMN signs point to the cord. This needs a medical review and imaging, not neck manipulation.","href":"/learn/radiculopathy-myelopathy-neuropathy","linkTitle":"Root, Cord or Nerve? Localising a Neurological Lesion"},{"id":"lq-radiculopathy-myelopathy-neuropathy-2","topic":"Skills · Neuro Exam","question":"Which finding is the strongest reason to refer urgently in a patient with neck pain and arm symptoms?","options":["Numbness in one dermatome that is slowly improving","Pain that is worse in the morning","New clumsy hands, a gait change, brisk reflexes and bladder urgency"],"correct":2,"explanation":"Yes — together these suggest progressive cord compression, which can cause permanent damage if not treated quickly.","href":"/learn/radiculopathy-myelopathy-neuropathy","linkTitle":"Root, Cord or Nerve? Localising a Neurological Lesion"},{"id":"lq-radiculopathy-myelopathy-neuropathy-3","topic":"Skills · Neuro Exam","question":"Which combination best fits a peripheral polyneuropathy?","options":["One myotome weak with matching dermatomal loss","Symmetrical glove-and-stocking numbness with reduced ankle jerks","Band-like trunk sensation with brisk leg reflexes"],"correct":1,"explanation":"Yes — the longest nerves fail first, so toes, feet and fingertips and the ankle jerks go first.","href":"/learn/radiculopathy-myelopathy-neuropathy","linkTitle":"Root, Cord or Nerve? Localising a Neurological Lesion"},{"id":"lq-reading-a-randomised-trial-1","topic":"Research & Evidence","question":"Which feature makes a trial's randomisation more trustworthy?","options":["A computer-generated sequence hidden from those enrolling patients","Alternating patients one by one","Giving treatment to patients who ask for it"],"correct":0,"explanation":"Yes — this prevents selection bias.","href":"/learn/reading-a-randomised-trial","linkTitle":"Reading a Randomised Trial — Bias, Confidence Intervals and What to Trust"},{"id":"lq-reading-a-randomised-trial-2","topic":"Research & Evidence","question":"A trial reports a 1-point difference in pain on a 0 to 10 scale, 95 percent CI 0.3 to 1.7, p = 0.006. What is the best interpretation?","options":["There is no effect because the difference is small","The treatment clearly works well for patients","The effect is probably real but may be too small to matter, since the usual important change is about 2 points"],"correct":2,"explanation":"Yes — compare the whole interval with the minimal important change.","href":"/learn/reading-a-randomised-trial","linkTitle":"Reading a Randomised Trial — Bias, Confidence Intervals and What to Trust"},{"id":"lq-reading-a-randomised-trial-3","topic":"Research & Evidence","question":"What does a wide confidence interval tell you?","options":["The study is biased","The effect is very large","The estimate is imprecise, often from a small study"],"correct":2,"explanation":"Yes — a wide interval means uncertainty.","href":"/learn/reading-a-randomised-trial","linkTitle":"Reading a Randomised Trial — Bias, Confidence Intervals and What to Trust"},{"id":"lq-red-flags-screening-1","topic":"Clinical Reasoning","question":"A 45-year-old with low back pain reports numbness \"where you sit on a bike seat\" and difficulty starting to pass urine since yesterday. What do you do?","options":["Gentle mobilization today, review in a week","Home exercises and rest","Same-day emergency referral for suspected cauda equina syndrome"],"correct":2,"explanation":"Exactly. Saddle numbness + new bladder change = emergency. Explain why, help them get there today, and document it.","href":"/learn/red-flags-screening","linkTitle":"Red Flags — When NOT to Treat (and What to Do Instead)"},{"id":"lq-red-flags-screening-2","topic":"Clinical Reasoning","question":"Which of these is a YELLOW flag?","options":["Constant night pain not changed by any position","Unexplained weight loss of 6 kg","A strong belief that the back is \"damaged\" and must be rested"],"correct":2,"explanation":"Yes — an unhelpful belief that drives fear and avoidance. You can change this with education and graded activity.","href":"/learn/red-flags-screening","linkTitle":"Red Flags — When NOT to Treat (and What to Do Instead)"},{"id":"lq-red-flags-screening-3","topic":"Clinical Reasoning","question":"During neck mobilization, the patient suddenly feels dizzy and sees double. What now?","options":["Stop immediately, keep them safe and arrange urgent medical assessment","Continue more gently","Switch to the other side of the neck"],"correct":0,"explanation":"Correct. Stop, monitor, don't let them leave alone, arrange urgent assessment and document everything.","href":"/learn/red-flags-screening","linkTitle":"Red Flags — When NOT to Treat (and What to Do Instead)"},{"id":"lq-return-to-sport-acl-criteria-1","topic":"Sports & Return to Play","question":"Which factor lowers the risk of a second ACL injury after reconstruction?","options":["Delaying return to pivoting sport and meeting strength and hop criteria","Returning as soon as the knee stops hurting","Returning at six months for everyone"],"correct":0,"explanation":"Yes — each month of delay and each criterion met lowers the risk.","href":"/learn/return-to-sport-acl-criteria","linkTitle":"Return to Sport After ACL Surgery — Criteria, Not the Calendar"},{"id":"lq-return-to-sport-acl-criteria-2","topic":"Sports & Return to Play","question":"An athlete has 95 percent hop symmetry and 80 percent quadriceps strength at eight months. What is the best decision?","options":["Stop sport altogether","Clear for full return because the hop result is good","Continue strengthening and retest before returning to pivoting sport"],"correct":2,"explanation":"Yes — quadriceps strength is below the target; keep training.","href":"/learn/return-to-sport-acl-criteria","linkTitle":"Return to Sport After ACL Surgery — Criteria, Not the Calendar"},{"id":"lq-return-to-sport-acl-criteria-3","topic":"Sports & Return to Play","question":"Why is psychological readiness part of the criteria?","options":["It does not affect performance","Fear and low confidence are linked to poorer return and re-injury","It is only for professionals"],"correct":1,"explanation":"Yes — readiness predicts return to sport.","href":"/learn/return-to-sport-acl-criteria","linkTitle":"Return to Sport After ACL Surgery — Criteria, Not the Calendar"},{"id":"lq-rolfing-structural-integration-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Structural integration mean?","options":["A traditional plan of about ten sessions.","A body-work method focusing on posture and fascia.","How the body is held and aligned."],"correct":1,"explanation":"Exactly! Structural integration — A body-work method focusing on posture and fascia.","href":"/manual-therapy/rolfing-structural-integration","linkTitle":"Rolfing / Structural Integration"},{"id":"lq-rolfing-structural-integration-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Rolfing / Structural Integration (or to stop and reassess)?","options":["People wanting a structured, longer program of bodywork with a trained practitioner.","Acute injuries, infection, blood clots, or serious medical conditions without clearance.","As a complement to exercise, not a replacement."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/rolfing-structural-integration","linkTitle":"Rolfing / Structural Integration"},{"id":"lq-rolfing-structural-integration-4","topic":"Manual Therapy · World Approaches","question":"After a bodywork session the patient stands taller. What is justified?","options":["Reassess comfort and activity rather than asserting permanent structural change.","Their skeletal alignment is now cured.","The fascia was permanently reshaped."],"correct":0,"explanation":"An observed postural or symptom change does not establish long-term tissue remodeling or superiority.","href":"/manual-therapy/rolfing-structural-integration","linkTitle":"Rolfing / Structural Integration"},{"id":"lq-romberg-tandem-pronator-drift-1","topic":"Skills · Neuro Exam","question":"A patient is steady with eyes open but sways and steps within seconds of closing his eyes. What is the most likely cause?","options":["A cerebellar lesion","Loss of proprioception (e.g. peripheral neuropathy or dorsal column disease)","A normal result"],"correct":1,"explanation":"Yes — vision was compensating for lost position sense; this is a classic positive Romberg.","href":"/learn/romberg-tandem-pronator-drift","linkTitle":"Romberg, Tandem Gait and Pronator Drift — Three Fast Neuro Screens"},{"id":"lq-romberg-tandem-pronator-drift-2","topic":"Skills · Neuro Exam","question":"In the pronator drift test, the left forearm slowly turns palm-down and sinks. What does it point to?","options":["A subtle upper motor neuron (pyramidal) lesion on the right side of the brain","Peripheral neuropathy","A cerebellar lesion"],"correct":0,"explanation":"Yes — pronation plus sinking is the classic pyramidal drift; the contralateral hemisphere is affected.","href":"/learn/romberg-tandem-pronator-drift","linkTitle":"Romberg, Tandem Gait and Pronator Drift — Three Fast Neuro Screens"},{"id":"lq-romberg-tandem-pronator-drift-3","topic":"Skills · Neuro Exam","question":"Which test narrows the base of support so the cerebellum must work hard?","options":["Pronator drift","Romberg","Tandem (heel-to-toe) gait"],"correct":2,"explanation":"Yes — walking heel-to-toe is the most sensitive bedside test for mild cerebellar disease.","href":"/learn/romberg-tandem-pronator-drift","linkTitle":"Romberg, Tandem Gait and Pronator Drift — Three Fast Neuro Screens"},{"id":"lq-scapulohumeral-rhythm-1","topic":"Movement Science","question":"A patient elevates the arm to 150°. Using the classic 2:1 rhythm, roughly how much came from scapular upward rotation?","options":["About 100°","About 50°","None — the scapula stays still"],"correct":1,"explanation":"Yes — one-third of 150° is 50° scapular, 100° glenohumeral (as a rough guide).","href":"/learn/scapulohumeral-rhythm","linkTitle":"Scapulohumeral Rhythm & Scapular Dyskinesis"},{"id":"lq-scapulohumeral-rhythm-2","topic":"Movement Science","question":"During a wall push-up, the whole medial border of the right scapula lifts off the ribs. Which muscle is most likely weak?","options":["Upper trapezius","Latissimus dorsi","Serratus anterior (long thoracic nerve)"],"correct":2,"explanation":"Yes — serratus anterior holds the scapula against the thorax. Medial winging on pushing is its classic sign.","href":"/learn/scapulohumeral-rhythm","linkTitle":"Scapulohumeral Rhythm & Scapular Dyskinesis"},{"id":"lq-scapulohumeral-rhythm-3","topic":"Movement Science","question":"A swimmer has slight scapular dyskinesis but no shoulder pain and full function. What should you do?","options":["Diagnose impingement and stop swimming","Note it; consider preventive strength work if load is rising — no alarm","Refer urgently for nerve conduction studies"],"correct":1,"explanation":"Right — it's common in pain-free athletes. Monitor and build capacity rather than label.","href":"/learn/scapulohumeral-rhythm","linkTitle":"Scapulohumeral Rhythm & Scapular Dyskinesis"},{"id":"lq-scar-mobilization-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Adherence mean?","options":["Lifting and rolling the skin between your fingers.","Small rubbing movements across the scar.","The scar sticking to deeper tissues so movement is limited."],"correct":2,"explanation":"Exactly! Adherence — The scar sticking to deeper tissues so movement is limited.","href":"/manual-therapy/scar-mobilization","linkTitle":"Scar Mobilization"},{"id":"lq-scar-mobilization-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Scar Mobilization (or to stop and reassess)?","options":["Healed scars after surgery or injury that feel tight or limit movement.","Cesarean, abdominal, hand or burn scars once cleared.","Open wound, scab, discharge, infection or unhealed sutures."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/scar-mobilization","linkTitle":"Scar Mobilization"},{"id":"lq-scoliosis-and-limb-alignment-1","topic":"Skills · Posture & Palpation","question":"A 12-year-old girl has a rib hump on forward bending and a scoliometer reading of 8°. What next?","options":["Reassure her it is posture and discharge","Start a strong stretching programme","Refer for a standing spinal X-ray (a reading of about 5–7° or more)"],"correct":2,"explanation":"Yes — the scoliometer screens; the X-ray measures the Cobb angle that decides observation, bracing or surgery.","href":"/learn/scoliosis-and-limb-alignment","linkTitle":"Scoliosis Screening and Limb Alignment — Adams Test, Knees and Feet"},{"id":"lq-scoliosis-and-limb-alignment-2","topic":"Skills · Posture & Palpation","question":"Which finding in a high-arched (cavus) foot should trigger a neurological referral?","options":["Claw toes with recurrent ankle sprains, a rigid foot and reduced ankle reflexes (consider Charcot–Marie–Tooth)","A flexible flat foot that is painless","A mild, symmetrical high arch in an athlete with no symptoms"],"correct":0,"explanation":"Yes — a cavus foot with progressive weakness and reduced reflexes suggests a hereditary neuropathy.","href":"/learn/scoliosis-and-limb-alignment","linkTitle":"Scoliosis Screening and Limb Alignment — Adams Test, Knees and Feet"},{"id":"lq-scoliosis-and-limb-alignment-3","topic":"Skills · Posture & Palpation","question":"What does the \"too many toes\" sign suggest when seen from behind?","options":["Normal foot alignment","Genu recurvatum","A collapsed medial arch with the heel tilted outward (pes planus / pronation)"],"correct":2,"explanation":"Yes — more toes are visible lateral to the heel because the forefoot has abducted and the heel has valgused.","href":"/learn/scoliosis-and-limb-alignment","linkTitle":"Scoliosis Screening and Limb Alignment — Adams Test, Knees and Feet"},{"id":"lq-sensitivity-specificity-1","topic":"Clinical Reasoning","question":"A test has very high sensitivity. The result is NEGATIVE. What can you say?","options":["The condition is confirmed","The condition is now unlikely","Nothing — sensitivity only matters for positive results"],"correct":1,"explanation":"That's SnNout in action! A sensitive test rarely misses the condition, so a negative result makes it unlikely.","href":"/learn/sensitivity-specificity","linkTitle":"Sensitivity, Specificity, SnNout & SpPin"},{"id":"lq-sensitivity-specificity-2","topic":"Clinical Reasoning","question":"A test has very high specificity and the result is POSITIVE. What's the best conclusion?","options":["The condition is ruled out","The condition becomes much more likely","The test is useless when positive"],"correct":1,"explanation":"SpPin! A specific test rarely fires in healthy people, so a positive result helps rule the condition in.","href":"/learn/sensitivity-specificity","linkTitle":"Sensitivity, Specificity, SnNout & SpPin"},{"id":"lq-sensory-exam-dermatomes-1","topic":"Skills · Neuro Exam","question":"A patient has numbness over the little finger and the inner forearm. Which root is most likely involved?","options":["C8","C6","C5"],"correct":0,"explanation":"Yes — the little finger is the \"8\" of the hand trick and the inner forearm is the C8 ribbon. Also check finger flexors and grip.","href":"/learn/sensory-exam-dermatomes","linkTitle":"Sensory Exam & Dermatomes — Find the Level by Touch"},{"id":"lq-sensory-exam-dermatomes-2","topic":"Skills · Neuro Exam","question":"A man has reduced pinprick over the outer shin, top of the foot and big toe on the right, with weak toe extension. Which level, and which disc is the classic culprit?","options":["S1 root — an L5–S1 disc","L3 root — an L2–L3 disc","L5 root — usually an L4–L5 disc (traversing root)"],"correct":2,"explanation":"Yes. Lumbar discs usually hit the root that is passing by (the traversing root), so L4–L5 compresses L5.","href":"/learn/sensory-exam-dermatomes","linkTitle":"Sensory Exam & Dermatomes — Find the Level by Touch"},{"id":"lq-sensory-exam-dermatomes-3","topic":"Skills · Neuro Exam","question":"Which tool detects loss of protective sensation in a diabetic foot?","options":["A tuning fork on the knee","A 10 g monofilament pressed on standard sites on the sole","A cotton ball on the shin"],"correct":1,"explanation":"Yes. If the patient cannot feel it at several sites, protective sensation is lost and the ulcer risk is high — teach daily foot checks.","href":"/learn/sensory-exam-dermatomes","linkTitle":"Sensory Exam & Dermatomes — Find the Level by Touch"},{"id":"lq-shoulder-cuff-tests-lag-signs-1","topic":"Skills · Measurement","question":"A 55-year-old cannot hold the arm in external rotation after you release it (lag sign) and cannot lower the abducted arm smoothly. What does this suggest?","options":["Simple rotator cuff-related pain managed with exercises only","A large rotator cuff tear needing specialist assessment","A frozen shoulder"],"correct":1,"explanation":"Yes — lag and drop-arm signs together suggest a large full-thickness tear.","href":"/learn/shoulder-cuff-tests-lag-signs","linkTitle":"The Painful Shoulder — Cuff Pain, Cuff Tears and the Tests That Tell Them Apart"},{"id":"lq-shoulder-cuff-tests-lag-signs-2","topic":"Skills · Measurement","question":"Which test assesses subscapularis?","options":["The Hornblower's sign","The empty can test","The belly-press test"],"correct":2,"explanation":"Yes — an elbow that drops back or a flexed wrist shows subscapularis weakness.","href":"/learn/shoulder-cuff-tests-lag-signs","linkTitle":"The Painful Shoulder — Cuff Pain, Cuff Tears and the Tests That Tell Them Apart"},{"id":"lq-shoulder-cuff-tests-lag-signs-3","topic":"Skills · Measurement","question":"A young rugby player feels the shoulder will come out when it is abducted and turned outwards. Which test confirms the pattern?","options":["The painful arc","The sulcus sign","The apprehension and relocation test"],"correct":2,"explanation":"Yes — apprehension that eases with a backward force on the humeral head points to anterior instability.","href":"/learn/shoulder-cuff-tests-lag-signs","linkTitle":"The Painful Shoulder — Cuff Pain, Cuff Tears and the Tests That Tell Them Apart"},{"id":"lq-sit-to-stand-tests-2","topic":"Skills · Balance & Function","question":"A patient uses their hands to push up on the third repetition of the 5×STS. What should you do?","options":["Stop, give the instruction again and restart; if the hands are always needed, record that the test could not be completed unaided","Continue and record the time","Count the repetition as half and carry on"],"correct":0,"explanation":"Yes — arm use changes the test; recording it is informative.","href":"/learn/sit-to-stand-tests","linkTitle":"Sit-to-Stand Tests — 5×STS and the 30-Second Chair Stand"},{"id":"lq-sit-to-stand-tests-3","topic":"Skills · Balance & Function","question":"Which score pattern suggests leg weakness rather than a poor balance problem?","options":["Normal 5×STS but frequent falls on uneven ground","A perfect score on every test","Slow 5×STS or low 30-second count with arms needed to push up"],"correct":2,"explanation":"Yes — sit-to-stand tests load the quadriceps and glutes, so slow performance with arm use points to weakness.","href":"/learn/sit-to-stand-tests","linkTitle":"Sit-to-Stand Tests — 5×STS and the 30-Second Chair Stand"},{"id":"lq-six-minute-walk-test-breathlessness-1","topic":"Skills · Vitals & Monitoring","question":"Which of these should be the same every time the test is repeated?","options":["Corridor length, instructions and encouragement","The patient's mood","The encouragement, chosen freely each time"],"correct":0,"explanation":"Yes — standardisation is what makes a change in distance meaningful.","href":"/learn/six-minute-walk-test-breathlessness","linkTitle":"The Six-Minute Walk Test — Measuring Breathlessness Safely"},{"id":"lq-six-minute-walk-test-breathlessness-2","topic":"Skills · Vitals & Monitoring","question":"A patient's distance rises from 280 to 295 metres after rehabilitation. What is the best conclusion?","options":["The change is small and may be within the test's normal variation; look at symptoms too","The test must be wrong","The treatment has clearly worked"],"correct":0,"explanation":"Yes — in chronic lung disease a change of about 30 metres is usually needed to be sure it is real.","href":"/learn/six-minute-walk-test-breathlessness","linkTitle":"The Six-Minute Walk Test — Measuring Breathlessness Safely"},{"id":"lq-six-minute-walk-test-breathlessness-3","topic":"Skills · Vitals & Monitoring","question":"Which finding means you should stop the test?","options":["A mild rise in heart rate","The patient asking about the time","Chest pain, severe breathlessness, dizziness or a pale, sweaty patient"],"correct":2,"explanation":"Yes — these are the standard stopping criteria; sit the patient down and monitor.","href":"/learn/six-minute-walk-test-breathlessness","linkTitle":"The Six-Minute Walk Test — Measuring Breathlessness Safely"},{"id":"lq-soft-tissue-mobilization-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Effleurage mean?","options":["Kneading or squeezing the muscle.","Long, gliding strokes used to warm up and finish.","Small, deeper circular or cross strokes on a specific area."],"correct":1,"explanation":"Exactly! Effleurage — Long, gliding strokes used to warm up and finish.","href":"/manual-therapy/soft-tissue-mobilization","linkTitle":"Soft-Tissue Mobilization"},{"id":"lq-soft-tissue-mobilization-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Soft-Tissue Mobilization (or to stop and reassess)?","options":["Muscle tension, soreness or stiffness limiting movement.","Preparing tissue before exercise or stretching.","Deep vein thrombosis, infection, open wounds, fractures or severe bruising."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/soft-tissue-mobilization","linkTitle":"Soft-Tissue Mobilization"},{"id":"lq-spasticity-tardieu-catch-lab-1","topic":"Neurology","question":"A patient's elbow flexors move freely through the whole range when stretched slowly, but catch at 40% of the range when stretched fast. What is the likeliest cause of the stiffness?","options":["Parkinsonian rigidity","Spasticity (a velocity-dependent stretch reflex)","A fixed contracture"],"correct":1,"explanation":"Yes — full range when slow plus an early catch when fast is the signature of spasticity, and a long R2 − R1 shows that the neural component is large.","href":"/learn/spasticity-tardieu-catch-lab","linkTitle":"Spasticity or Contracture? The Tardieu Catch Lab"},{"id":"lq-spasticity-tardieu-catch-lab-2","topic":"Neurology","question":"A child's calf muscle reaches only 15° of dorsiflexion even at the slowest speed, and fast stretches do not change that angle. What does this show?","options":["Normal muscle length with high tone","A fixed contracture: the problem is tissue length, not a reflex","Severe spasticity that needs tone-reducing drugs first"],"correct":1,"explanation":"Yes — a short R2 that does not depend on speed means non-neural shortening. Slowing down will not release a muscle that is simply short.","href":"/learn/spasticity-tardieu-catch-lab","linkTitle":"Spasticity or Contracture? The Tardieu Catch Lab"},{"id":"lq-spasticity-tardieu-catch-lab-3","topic":"Neurology","question":"Why is the Modified Ashworth Scale limited for deciding between tone management and stretching?","options":["It is too complex to repeat","It can only be used on the upper limb","It does not control the speed and cannot tell reflex resistance from soft-tissue stiffness"],"correct":2,"explanation":"Yes — one number mixes both causes, so it cannot say whether tone or length is the main problem.","href":"/learn/spasticity-tardieu-catch-lab","linkTitle":"Spasticity or Contracture? The Tardieu Catch Lab"},{"id":"lq-special-tests-sensitivity-clusters-1","topic":"Clinical Reasoning","question":"A test has a positive LR of 1.2. What does a positive result do?","options":["It rules out the diagnosis","Almost nothing: it barely changes the odds","It confirms the diagnosis"],"correct":1,"explanation":"Yes — an LR close to 1 is nearly useless for changing a decision.","href":"/learn/special-tests-sensitivity-clusters","linkTitle":"Using Special Tests Wisely — Rule In, Rule Out and Clusters"},{"id":"lq-special-tests-sensitivity-clusters-2","topic":"Clinical Reasoning","question":"The pre-test chance is 30% and a test has a negative LR of 0.2. About what is the chance after a negative result?","options":["About 8%","About 60%","About 30%, unchanged"],"correct":0,"explanation":"Yes — odds of 0.43 times 0.2 is about 0.086, which is about 8%.","href":"/learn/special-tests-sensitivity-clusters","linkTitle":"Using Special Tests Wisely — Rule In, Rule Out and Clusters"},{"id":"lq-special-tests-sensitivity-clusters-3","topic":"Clinical Reasoning","question":"You need to be confident enough to rule a condition out. Which kind of test result helps most?","options":["A negative result on a highly sensitive test","A positive result on a highly specific test","A negative result on a test with a negative LR near 1"],"correct":0,"explanation":"Yes — a very sensitive test misses few true cases, so a negative result is reassuring (SnNout).","href":"/learn/special-tests-sensitivity-clusters","linkTitle":"Using Special Tests Wisely — Rule In, Rule Out and Clusters"},{"id":"lq-spencer-shoulder-sequence-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Adhesive capsulitis mean?","options":["Frozen shoulder: painful, progressive stiffness of the shoulder joint capsule.","Moving the arm in a circle.","Lying on the unaffected side."],"correct":0,"explanation":"Exactly! Adhesive capsulitis — Frozen shoulder: painful, progressive stiffness of the shoulder joint capsule.","href":"/manual-therapy/spencer-shoulder-sequence","linkTitle":"Spencer Shoulder Technique"},{"id":"lq-spencer-shoulder-sequence-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Spencer Shoulder Technique (or to stop and reassess)?","options":["A stiff shoulder in the stiff or recovery phase, once other causes have been screened.","Shoulder fracture, dislocation, severe pain or infection.","Practitioners trained in the technique."],"correct":1,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/spencer-shoulder-sequence","linkTitle":"Spencer Shoulder Technique"},{"id":"lq-spencer-shoulder-sequence-4","topic":"Manual Therapy · World Approaches","question":"A patient has acute traumatic inability to raise the arm. What should happen before any Spencer sequence?","options":["Assume stiffness from posture.","Check for serious structural injury and consider timely referral.","Complete all directions rapidly."],"correct":1,"explanation":"New major weakness after trauma needs examination and potential imaging/referral before guided mobilization.","href":"/manual-therapy/spencer-shoulder-sequence","linkTitle":"Spencer Shoulder Technique"},{"id":"lq-spinal-and-general-measures-1","topic":"Skills · Measurement","question":"The modified Schober measurement goes from 15 cm to 17 cm on full forward bend. What does it suggest?","options":["Reduced lumbar flexion (normal is 5 cm or more of increase); look for causes such as inflammatory back pain","Normal flexion","Hypermobility"],"correct":0,"explanation":"Yes — a 2 cm increase is well below normal and, with other features, can fit axial spondyloarthritis.","href":"/learn/spinal-and-general-measures","linkTitle":"Spinal Mobility and General Measures — Schober, Chest Expansion, Occiput-Wall, Grip and BMI"},{"id":"lq-spinal-and-general-measures-2","topic":"Skills · Measurement","question":"Why is the grip dynamometer position kept the same every time?","options":["To make the patient squeeze harder","To protect the dynamometer","Grip force depends on handle width and arm position, so changes would alter the result"],"correct":2,"explanation":"Yes — standardisation is what makes a change between visits trustworthy.","href":"/learn/spinal-and-general-measures","linkTitle":"Spinal Mobility and General Measures — Schober, Chest Expansion, Occiput-Wall, Grip and BMI"},{"id":"lq-spinal-and-general-measures-3","topic":"Skills · Measurement","question":"A patient's chest expansion is 1.5 cm with morning stiffness over an hour and a young age. What is a sensible next step?","options":["Reassure that it is normal","Suspect inflammatory back disease and refer for medical assessment while keeping the spine mobile","Start high-velocity spinal manipulation"],"correct":1,"explanation":"Yes — this pattern needs rheumatology review; exercise and posture work remain useful in the meantime.","href":"/learn/spinal-and-general-measures","linkTitle":"Spinal Mobility and General Measures — Schober, Chest Expansion, Occiput-Wall, Grip and BMI"},{"id":"lq-spinal-cord-syndromes-brown-sequard-1","topic":"Neurology","question":"A stab wound halves the RIGHT side of the cord at T10. What do you expect on examination?","options":["Left leg weak with lost pain on the right","Both legs weak, all sensation lost on both sides","Right leg weak with lost position and vibration sense; left leg lost pain and temperature"],"correct":2,"explanation":"Yes — strength and position sense stay on the lesion side, while pain and temperature have crossed, so they are lost on the opposite side.","href":"/learn/spinal-cord-syndromes-brown-sequard","linkTitle":"Brown-Séquard and the Cord Syndromes: Which Side Is Weak, Which Side Is Numb?"},{"id":"lq-spinal-cord-syndromes-brown-sequard-2","topic":"Neurology","question":"An 70-year-old with cervical spondylosis falls forward and lands on her chin. She cannot lift her arms well, her legs are stronger, her hands burn and she has trouble with her bladder. Which syndrome?","options":["Brown-Séquard syndrome","Central cord syndrome","Posterior cord syndrome"],"correct":1,"explanation":"Yes — arms worse than legs with burning hands and bladder trouble is the classic central cord picture. The arm fibres sit more medially in the corticospinal tract, closer to the damaged centre.","href":"/learn/spinal-cord-syndromes-brown-sequard","linkTitle":"Brown-Séquard and the Cord Syndromes: Which Side Is Weak, Which Side Is Numb?"},{"id":"lq-still-technique-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Somatic dysfunction mean?","options":["An osteopathic term for impaired movement of a body region.","Moving toward the restriction.","Moving toward the easy direction."],"correct":0,"explanation":"Exactly! Somatic dysfunction — An osteopathic term for impaired movement of a body region.","href":"/manual-therapy/still-technique","linkTitle":"Still Technique"},{"id":"lq-still-technique-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Still Technique (or to stop and reassess)?","options":["Fractures, instability, infection or blood-vessel concerns.","Stiff, tender joints or regions where a gentle method is wanted.","Practitioners trained in osteopathic techniques."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/still-technique","linkTitle":"Still Technique"},{"id":"lq-still-technique-4","topic":"Manual Therapy · World Approaches","question":"Why is an audible pop a poor treatment goal?","options":["It does not reliably prove better function or corrected anatomy.","It confirms the original diagnosis.","It is always essential for pain relief."],"correct":0,"explanation":"Clinical success is judged by safety, meaningful function and symptom response rather than joint noise.","href":"/manual-therapy/still-technique","linkTitle":"Still Technique"},{"id":"lq-strain-counterstrain-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Tender point mean?","options":["The position where the tender point hurts least.","A small, sore spot found by gentle pressure, used as a monitor for positioning.","A 0-10 rating the patient gives when you press the point."],"correct":1,"explanation":"Exactly! Tender point — A small, sore spot found by gentle pressure, used as a monitor for positioning.","href":"/manual-therapy/strain-counterstrain","linkTitle":"Strain Counterstrain / Positional Release"},{"id":"lq-strain-counterstrain-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Strain Counterstrain / Positional Release (or to stop and reassess)?","options":["Unstable fracture or serious joint or spine instability.","Acute or irritable muscle or joint tenderness where stretching hurts.","Patients who cannot tolerate firm treatment."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/strain-counterstrain","linkTitle":"Strain Counterstrain / Positional Release"},{"id":"lq-stroke-syndromes-by-territory-1","topic":"Neurology","question":"A man has a sudden weak left leg, a mildly weak left arm, loses his drive and cannot control his bladder. His face and speech are normal. Which artery?","options":["Right anterior cerebral artery","Right middle cerebral artery","Left posterior cerebral artery"],"correct":0,"explanation":"Yes — a leg-predominant weakness with apathy (abulia) and incontinence is the classic ACA picture: the leg area and frontal control sit on the inner surface.","href":"/learn/stroke-syndromes-by-territory","linkTitle":"Stroke Syndromes: Read the Artery from the Body"},{"id":"lq-stroke-syndromes-by-territory-2","topic":"Neurology","question":"Mrs K, 68, has a stroke. She eats only the food on the right half of her plate, never looks to the left, and says \"my left arm is fine\" while it hangs limp. Which side is the damaged hemisphere?","options":["Brainstem: lateral medullary syndrome","Right hemisphere (right MCA): neglect and anosognosia of the left side","Left hemisphere (left MCA): aphasia"],"correct":1,"explanation":"Yes — the right hemisphere builds our awareness of space and body, so damage produces neglect and lack of insight on the opposite (left) side.","href":"/learn/stroke-syndromes-by-territory","linkTitle":"Stroke Syndromes: Read the Artery from the Body"},{"id":"lq-stroke-syndromes-by-territory-3","topic":"Neurology","question":"A patient has sudden vertigo and vomiting, a hoarse voice and difficulty swallowing, loses pain and temperature on the RIGHT side of the face and the LEFT side of the body, and has a small right pupil. Where is the lesion?","options":["Right lateral medulla (Wallenberg: PICA or vertebral artery)","Left ACA","Left MCA"],"correct":0,"explanation":"Yes — face on the lesion side and body on the opposite side is the crossed pattern unique to the lateral medulla. The small pupil is Horner's syndrome on the same side.","href":"/learn/stroke-syndromes-by-territory","linkTitle":"Stroke Syndromes: Read the Artery from the Body"},{"id":"lq-stroke-syndromes-by-territory-4","topic":"Neurology","question":"Why is the hemiparetic (weak-sided) shoulder vulnerable during transfers?","options":["Because patients with stroke cannot feel their shoulders at all","Because the shoulder is always stiff after a stroke","The muscles that hold the humeral head in the socket are weak and the arm hangs, so pulling on it can subluxate or injure the joint"],"correct":2,"explanation":"Yes — the passive restraints take the load, so the arm must be supported, never pulled.","href":"/learn/stroke-syndromes-by-territory","linkTitle":"Stroke Syndromes: Read the Artery from the Body"},{"id":"lq-subjective-assessment-sin-1","topic":"Clinical Reasoning","question":"Mrs Khan says 5 minutes of standing brings on 8/10 back pain, and it takes 2–3 hours of lying down to settle. Her irritability is…","options":["Can't tell without an MRI","Low","High"],"correct":2,"explanation":"Yes. Easy to provoke, severe, slow to settle = highly irritable. Plan a short, gentle examination.","href":"/learn/subjective-assessment-sin","linkTitle":"Subjective Assessment — SIN, Irritability & the 24-Hour Pattern"},{"id":"lq-subjective-assessment-sin-2","topic":"Clinical Reasoning","question":"Which history finding should most change the NATURE in your SIN?","options":["Pain 4/10 in the evening","Past breast cancer, new thoracic pain, weight loss","Pain worse after gardening"],"correct":1,"explanation":"Yes — possible metastatic disease. The nature is now 'serious pathology until proven otherwise'; refer promptly.","href":"/learn/subjective-assessment-sin","linkTitle":"Subjective Assessment — SIN, Irritability & the 24-Hour Pattern"},{"id":"lq-subjective-assessment-sin-3","topic":"Clinical Reasoning","question":"A footballer's knee hurts only after 60 minutes of matches (4/10) and settles within 10 minutes. How should you examine?","options":["Fully: end-range, overpressure, hopping and sport-specific tests","Gently, stopping at the first pain","Don't examine — send for an MRI first"],"correct":0,"explanation":"Right — low irritability. You need high-load tests to find the problem.","href":"/learn/subjective-assessment-sin","linkTitle":"Subjective Assessment — SIN, Irritability & the 24-Hour Pattern"},{"id":"lq-tendinopathy-load-management-1","topic":"Tissue Healing","question":"A runner with Achilles tendinopathy asks if complete rest for 6 weeks will fix it. Best answer?","options":["Yes — rest lets the inflammation settle","No — we'll adjust your load and start a progressive tendon-loading programme","Only surgery works for tendons"],"correct":1,"explanation":"Yes — modify aggravating loads (e.g. hills, speed work) and build tendon capacity with progressive loading.","href":"/learn/tendinopathy-load-management","linkTitle":"Tendinopathy & Load Management — Why Rest Fails and Loading Works"},{"id":"lq-tendinopathy-load-management-2","topic":"Tissue Healing","question":"After heavy slow calf raises, your patient's Achilles pain was 3/10 during, settled overnight, and morning stiffness is less than last week. What next?","options":["Stop exercise and use ultrasound instead","Progress — e.g. add load or move towards single-leg work","Reduce the load — any pain is bad"],"correct":1,"explanation":"Yes — all three rules are met and the trend is improving, so progress one variable.","href":"/learn/tendinopathy-load-management","linkTitle":"Tendinopathy & Load Management — Why Rest Fails and Loading Works"},{"id":"lq-tendinopathy-load-management-3","topic":"Tissue Healing","question":"Which patient should you NOT treat as simple tendinopathy?","options":["Sudden calf 'pop' while playing, now can't push off; Thompson's test shows no plantarflexion","Lateral elbow pain after a week of painting","Gradual Achilles pain after increasing weekly mileage"],"correct":0,"explanation":"Likely Achilles rupture — urgent orthopaedic referral, not a loading programme.","href":"/learn/tendinopathy-load-management","linkTitle":"Tendinopathy & Load Management — Why Rest Fails and Loading Works"},{"id":"lq-tens-ultrasound-evidence-1","topic":"Electrotherapy","question":"Your patient feels only a faint tingle from conventional TENS after 15 minutes. What should you do?","options":["Turn the intensity up to strong but comfortable again","Switch it off — TENS has failed","Leave it — a faint tingle is enough"],"correct":0,"explanation":"Yes — nerves habituate, so adjust intensity to keep a strong, non-painful sensation.","href":"/learn/tens-ultrasound-evidence","linkTitle":"TENS & Therapeutic Ultrasound — Parameters, Safety & What the Evidence Really Says"},{"id":"lq-tens-ultrasound-evidence-2","topic":"Electrotherapy","question":"Which patient should NOT receive TENS over the stated area?","options":["Knee OA, electrodes around the knee","Chronic low back pain, electrodes on the lower back","A patient with a demand pacemaker, electrodes on the chest"],"correct":2,"explanation":"Yes — risk of interference with the pacemaker. Avoid unless specifically cleared by cardiology.","href":"/learn/tens-ultrasound-evidence","linkTitle":"TENS & Therapeutic Ultrasound — Parameters, Safety & What the Evidence Really Says"},{"id":"lq-tens-ultrasound-evidence-3","topic":"Electrotherapy","question":"A patient with knee OA has had 10 sessions of ultrasound and hot packs with no change. What's the best next step?","options":["Refer immediately for knee replacement","Education plus progressive strengthening and activity, with TENS only if it helps them exercise","Ten more sessions at a higher dose"],"correct":1,"explanation":"Yes — exercise and education are first-line for knee OA; modalities are optional adjuncts.","href":"/learn/tens-ultrasound-evidence","linkTitle":"TENS & Therapeutic Ultrasound — Parameters, Safety & What the Evidence Really Says"},{"id":"lq-thoracic-manipulation-neck-pain-1","topic":"Manual Therapy · Joint","question":"A patient with severe, irritable neck pain, high anxiety and a very stiff upper back needs treatment today. What is the better choice?","options":["No treatment at all","A forceful thrust to the whole spine","Non-thrust thoracic mobilisation, with advice and gentle movement"],"correct":2,"explanation":"Yes — it is gentler, can still reduce pain and fits an irritable, anxious patient.","href":"/learn/thoracic-manipulation-neck-pain","linkTitle":"Thoracic Spine Manipulation for Neck Pain — Choosing Thrust or Non-Thrust"},{"id":"lq-thoracic-manipulation-neck-pain-2","topic":"Manual Therapy · Joint","question":"Which patient should not have a thoracic thrust?","options":["A healthy 30-year-old with a stiff upper back and no red flags","A patient who has agreed after you explained the options","A patient with osteoporosis and a recent fall, or with a history of cancer and night pain"],"correct":2,"explanation":"Yes — a fracture risk or a possible serious condition is a reason not to thrust and to refer.","href":"/learn/thoracic-manipulation-neck-pain","linkTitle":"Thoracic Spine Manipulation for Neck Pain — Choosing Thrust or Non-Thrust"},{"id":"lq-thoracic-manipulation-neck-pain-3","topic":"Manual Therapy · Joint","question":"What should you do straight after the technique?","options":["Send the patient home without advice","Re-test the movement and pain, then teach an exercise","Repeat the thrust several times"],"correct":1,"explanation":"Yes — re-testing shows the effect and the exercise helps to keep it.","href":"/learn/thoracic-manipulation-neck-pain","linkTitle":"Thoracic Spine Manipulation for Neck Pain — Choosing Thrust or Non-Thrust"},{"id":"lq-timed-up-and-go-gait-speed-1","topic":"Skills · Balance & Function","question":"Which action stops the timer in the TUG?","options":["When the patient reaches the cone","When the patient's back touches the chair after sitting down","When the patient stands up"],"correct":1,"explanation":"Yes — the whole cycle is stand, walk, turn, return and sit.","href":"/learn/timed-up-and-go-gait-speed","linkTitle":"Timed Up and Go and Gait Speed — Two Minutes That Predict a Lot"},{"id":"lq-timed-up-and-go-gait-speed-2","topic":"Skills · Balance & Function","question":"A patient needs 14 seconds for the TUG and 0.7 m/s for gait speed. What is the best summary?","options":["Both are normal for age","The patient is safe to walk unsupervised outdoors","Increased falls risk and limited community walking; start strength, balance and walking practice and check the home"],"correct":2,"explanation":"Yes — both measures point the same way; combine them with history and other risk factors.","href":"/learn/timed-up-and-go-gait-speed","linkTitle":"Timed Up and Go and Gait Speed — Two Minutes That Predict a Lot"},{"id":"lq-timed-up-and-go-gait-speed-3","topic":"Skills · Balance & Function","question":"What gait speed is generally needed to cross a street safely?","options":["About 1.2 m/s (traffic-light times are designed around it)","About 2.0 m/s","About 0.4 m/s"],"correct":0,"explanation":"Yes — many older adults walk slower than this, so crossing safely needs targeted training.","href":"/learn/timed-up-and-go-gait-speed","linkTitle":"Timed Up and Go and Gait Speed — Two Minutes That Predict a Lot"},{"id":"lq-tissue-healing-phases-1","topic":"Tissue Healing","question":"Day 10 after a moderate ankle sprain. Swelling is reducing; pain only with stress. Most likely phase, and what should treatment emphasise?","options":["Inflammatory — complete rest","Remodelling — full sport training","Proliferative — gradual, controlled loading and range of motion"],"correct":2,"explanation":"Exactly. New collagen is being laid down — controlled load helps it line up and get stronger.","href":"/learn/tissue-healing-phases","linkTitle":"Tissue Healing Phases — What to Do and When"},{"id":"lq-tissue-healing-phases-2","topic":"Tissue Healing","question":"Which statement about the remodelling phase is TRUE?","options":["It finishes as soon as the pain stops","Collagen keeps maturing and getting stronger for months","It happens in the first 48 hours"],"correct":1,"explanation":"Correct! Remodelling can continue for many months — progressive loading during this time is what makes the tissue strong.","href":"/learn/tissue-healing-phases","linkTitle":"Tissue Healing Phases — What to Do and When"},{"id":"lq-tissue-healing-phases-3","topic":"Tissue Healing","question":"A footballer's hamstring strain is pain-free at 2 weeks. He wants to sprint in a match this weekend. Best response?","options":["Yes — pain-free means healed","Keep progressing load; return when strength and sprint tests meet criteria","Rest completely for 3 more months"],"correct":1,"explanation":"Exactly — criteria-based return to sport protects him far better than the calendar or pain alone.","href":"/learn/tissue-healing-phases","linkTitle":"Tissue Healing Phases — What to Do and When"},{"id":"lq-tone-spasticity-rigidity-ashworth-1","topic":"Skills · Neuro Exam","question":"A patient's elbow resists more the faster you extend it, with a catch at mid-range and then a release. What is this called?","options":["Spasticity (velocity-dependent, clasp-knife)","Flaccidity","Rigidity"],"correct":0,"explanation":"Yes — the catch-and-release that gets stronger with speed is spasticity, an upper motor neuron sign.","href":"/learn/tone-spasticity-rigidity-ashworth","linkTitle":"Muscle Tone — Spasticity, Rigidity and the Modified Ashworth Scale"},{"id":"lq-tone-spasticity-rigidity-ashworth-2","topic":"Skills · Neuro Exam","question":"A patient has R1 = 40° and R2 = 90° on the Tardieu scale. What does the large gap suggest?","options":["Normal tone","A fixed contracture needing casting or surgery","Much of the restriction is dynamic spasticity, so tone management, positioning and stretching can help"],"correct":2,"explanation":"Yes — a big R2 − R1 gap means the muscle can lengthen when the stretch is slow; spasticity is the main problem.","href":"/learn/tone-spasticity-rigidity-ashworth","linkTitle":"Muscle Tone — Spasticity, Rigidity and the Modified Ashworth Scale"},{"id":"lq-tone-spasticity-rigidity-ashworth-3","topic":"Skills · Neuro Exam","question":"Which finding best fits Parkinsonian rigidity?","options":["Uniform resistance at all speeds, with a ratchet-like cogwheel when tremor is present","Almost no resistance and floppy limbs","A catch that grows with speed and a release"],"correct":0,"explanation":"Yes — velocity-independent rigidity with cogwheeling is typical of basal ganglia disease.","href":"/learn/tone-spasticity-rigidity-ashworth","linkTitle":"Muscle Tone — Spasticity, Rigidity and the Modified Ashworth Scale"},{"id":"lq-total-hip-replacement-rehab-1","topic":"Post-operative Rehab","question":"Who decides the hip precautions that a patient must follow?","options":["The surgeon, based on the surgical approach and the individual patient","The patient's preference","The physiotherapist alone"],"correct":0,"explanation":"Yes — follow the written instructions and explain why.","href":"/learn/total-hip-replacement-rehab","linkTitle":"After a Total Hip Replacement — Precautions, Walking and Strength"},{"id":"lq-total-hip-replacement-rehab-2","topic":"Post-operative Rehab","question":"Which finding suggests a dislocated hip replacement?","options":["A little bruising around the thigh","Mild aching after a long walk","Sudden severe hip pain, a shortened and turned leg and inability to bear weight"],"correct":2,"explanation":"Yes — this is an emergency needing urgent medical care.","href":"/learn/total-hip-replacement-rehab","linkTitle":"After a Total Hip Replacement — Precautions, Walking and Strength"},{"id":"lq-total-hip-replacement-rehab-3","topic":"Post-operative Rehab","question":"What should you do if the patient has a calf that is hot, swollen and painful?","options":["Wait a week to see if it settles","Stop exercise and arrange urgent medical assessment for a possible clot","Massage the calf to relieve it"],"correct":1,"explanation":"Yes — avoid massage or exercise of the leg and get urgent assessment.","href":"/learn/total-hip-replacement-rehab","linkTitle":"After a Total Hip Replacement — Precautions, Walking and Strength"},{"id":"lq-total-knee-replacement-rehab-1","topic":"Post-operative Rehab","question":"By roughly when should a patient reach 90 degrees of knee bending after a total knee replacement?","options":["After six months","It does not matter","Within the first two weeks"],"correct":2,"explanation":"Yes — early range is a common target and is hard to regain later.","href":"/learn/total-knee-replacement-rehab","linkTitle":"After a Total Knee Replacement — Early Movement, Strength and Safety"},{"id":"lq-total-knee-replacement-rehab-2","topic":"Post-operative Rehab","question":"Which finding after a knee replacement needs urgent review?","options":["Mild swelling that goes down with rest and elevation","Muscle ache the day after exercise","A hot, red, swollen knee with fever or a wound that is leaking"],"correct":2,"explanation":"Yes — these suggest infection and need the surgical team at once.","href":"/learn/total-knee-replacement-rehab","linkTitle":"After a Total Knee Replacement — Early Movement, Strength and Safety"},{"id":"lq-total-knee-replacement-rehab-3","topic":"Post-operative Rehab","question":"A calf that is hot, tender and swollen after surgery may mean what?","options":["A normal healing sign","A sign of strong muscles","A deep vein thrombosis, which needs urgent medical assessment"],"correct":2,"explanation":"Yes — do not massage or exercise the leg; seek urgent assessment.","href":"/learn/total-knee-replacement-rehab","linkTitle":"After a Total Knee Replacement — Early Movement, Strength and Safety"},{"id":"lq-training-load-injury-risk-1","topic":"Sports & Return to Play","question":"Which athlete is at greatest risk of overuse injury?","options":["One who doubles weekly running distance after a break","One who rests a lot and trains lightly","One who trains steadily at a high load for months"],"correct":0,"explanation":"Yes — a sudden large jump in load exceeds what tissues are used to.","href":"/learn/training-load-injury-risk","linkTitle":"Training Load and Injury Risk — Building Athletes, Not Breaking Them"},{"id":"lq-training-load-injury-risk-2","topic":"Sports & Return to Play","question":"A runner's weekly distance goes from 20 to 45 kilometres in two weeks and her shins hurt. What is the best response?","options":["Stop all exercise for six months","Increase again to build tolerance","Reduce load now, explain the build-up, and restart with a gradual plan"],"correct":2,"explanation":"Yes — the spike probably explains the pain; early action prevents a stress injury.","href":"/learn/training-load-injury-risk","linkTitle":"Training Load and Injury Risk — Building Athletes, Not Breaking Them"},{"id":"lq-training-load-injury-risk-3","topic":"Sports & Return to Play","question":"Which sign should prompt a medical review?","options":["General tiredness the day after a hard session","Pain at one bone point that is worse at night with a rising load","Mild muscle soreness for two days"],"correct":1,"explanation":"Yes — this can be a stress fracture and needs imaging.","href":"/learn/training-load-injury-risk","linkTitle":"Training Load and Injury Risk — Building Athletes, Not Breaking Them"},{"id":"lq-trigger-point-compression-1","topic":"Manual Therapy · Soft Tissue","question":"Vocabulary first — clinicians use this word a lot. What does Trigger point mean?","options":["A tight, rope-like strip of muscle.","A tender spot in a taut muscle band that can reproduce or refer pain.","Pain felt away from the pressed spot, for example neck knot causing headache."],"correct":1,"explanation":"Exactly! Trigger point — A tender spot in a taut muscle band that can reproduce or refer pain.","href":"/manual-therapy/trigger-point-compression","linkTitle":"Trigger-Point Pressure Release"},{"id":"lq-trigger-point-compression-2","topic":"Manual Therapy · Soft Tissue","question":"Safety check: which of these is a reason NOT to use Trigger-Point Pressure Release (or to stop and reassess)?","options":["Infection, open wounds, or fragile skin.","Headaches from neck and shoulder muscles.","Muscle pain with a clear tender spot that reproduces the patient's pain."],"correct":0,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/trigger-point-compression","linkTitle":"Trigger-Point Pressure Release"},{"id":"lq-umn-vs-lmn-1","topic":"Neurology","question":"After a stroke, a patient has increased tone, brisk reflexes and an up-going plantar response on the right. Lesion type?","options":["LMN lesion","UMN lesion","Primary muscle disease"],"correct":1,"explanation":"Correct — the manager is gone: tone up, reflexes up, toes up. And because the motor pathway crosses in the medulla, a left-brain stroke affects the right side.","href":"/learn/umn-vs-lmn","linkTitle":"UMN vs LMN Lesions — Never Confuse Them Again"},{"id":"lq-umn-vs-lmn-2","topic":"Neurology","question":"After a common fibular (peroneal) nerve injury, a patient has foot drop, a floppy ankle and wasting of the front of the leg. Lesion type?","options":["LMN lesion","UMN lesion"],"correct":0,"explanation":"Yes — the worker's wire was cut. Peripheral nerve damage = LMN: flaccid, wasting, in that nerve's muscles only.","href":"/learn/umn-vs-lmn","linkTitle":"UMN vs LMN Lesions — Never Confuse Them Again"},{"id":"lq-umn-vs-lmn-3","topic":"Neurology","question":"You move a patient's elbow slowly — little resistance. You move it fast — strong resistance that suddenly gives way. This is…","options":["Normal tone","Spasticity","Rigidity"],"correct":1,"explanation":"Exactly — velocity-dependent with a clasp-knife release. A UMN sign.","href":"/learn/umn-vs-lmn","linkTitle":"UMN vs LMN Lesions — Never Confuse Them Again"},{"id":"lq-upper-motor-neuron-signs-bedside-1","topic":"Skills · Neuro Exam","question":"On stroking the sole, the great toe extends and the other toes fan out. What does this show?","options":["An upper motor neuron lesion (a positive Babinski sign)","A normal response","A lower motor neuron lesion"],"correct":0,"explanation":"Yes — the extensor plantar response means the corticospinal pathway is damaged. Look for other UMN signs and refer if it is new.","href":"/learn/upper-motor-neuron-signs-bedside","linkTitle":"UMN Signs at the Bedside — Babinski, Hoffmann, Clonus and the Jaw Jerk"},{"id":"lq-upper-motor-neuron-signs-bedside-2","topic":"Skills · Neuro Exam","question":"How many beats of ankle clonus are considered abnormal?","options":["Any single beat","Only when the patient feels pain","More than about 5 beats, or beats that continue while the stretch is held"],"correct":2,"explanation":"Yes — one to three beats can be normal in a brisk, relaxed patient; sustained clonus is a UMN sign.","href":"/learn/upper-motor-neuron-signs-bedside","linkTitle":"UMN Signs at the Bedside — Babinski, Hoffmann, Clonus and the Jaw Jerk"},{"id":"lq-upper-motor-neuron-signs-bedside-3","topic":"Skills · Neuro Exam","question":"Which combination points most clearly to an UMN lesion?","options":["Reduced reflexes, weak muscles and glove-and-stocking numbness","Brisk reflexes, sustained clonus, upgoing toe and spasticity","Absent reflexes, wasted muscles and fasciculations"],"correct":1,"explanation":"Yes — several UMN signs together are convincing.","href":"/learn/upper-motor-neuron-signs-bedside","linkTitle":"UMN Signs at the Bedside — Babinski, Hoffmann, Clonus and the Jaw Jerk"},{"id":"lq-visceral-manipulation-1","topic":"Manual Therapy · World Approaches","question":"Vocabulary first — clinicians use this word a lot. What does Viscera mean?","options":["Sudden severe abdominal pain needing urgent medical review.","Connective tissue linking organs to the body wall.","The internal organs, such as intestines and liver."],"correct":2,"explanation":"Exactly! Viscera — The internal organs, such as intestines and liver.","href":"/manual-therapy/visceral-manipulation","linkTitle":"Visceral Manipulation / Visceral Fascial Therapy"},{"id":"lq-visceral-manipulation-2","topic":"Manual Therapy · World Approaches","question":"Safety check: which of these is a reason NOT to use Visceral Manipulation / Visceral Fascial Therapy (or to stop and reassess)?","options":["As an adjunct, never as the main treatment for a disease.","Trained practitioners offering gentle abdominal touch for comfort when medically cleared.","Acute abdominal pain, fever, vomiting, bleeding, pregnancy complications or unexplained weight loss."],"correct":2,"explanation":"Exactly — that's a stop sign. In that situation you stop, reassess, adapt or refer before any hands-on treatment.","href":"/manual-therapy/visceral-manipulation","linkTitle":"Visceral Manipulation / Visceral Fascial Therapy"},{"id":"lq-visceral-manipulation-4","topic":"Manual Therapy · World Approaches","question":"A patient with new severe abdominal pain asks for visceral manipulation. Best action?","options":["Consider urgent medical assessment and defer manual treatment.","Promise that an organ release will correct the problem.","Use firm abdominal pressure to break fascial restrictions."],"correct":0,"explanation":"New severe abdominal pain is a medical assessment issue. Manual bodywork should not delay appropriate urgent care.","href":"/manual-therapy/visceral-manipulation","linkTitle":"Visceral Manipulation / Visceral Fascial Therapy"}];
